// Element definitions and the battle effectiveness matrix.
// Every attack element maps to multipliers against defending elements.
// 2 = super effective, 0.5 = resisted, 1 = neutral.

export const ELEMENTS = {
  none:   { name: 'Neutral', color: '#d8cbb6', dark: '#6d6252', light: '#f4ecdd', glyph: '◇' },
  nature: { name: 'Nature',  color: '#74ce6a', dark: '#2f6b3d', light: '#c3f5a5', glyph: '✿' },
  flame:  { name: 'Flame',   color: '#ff8a4c', dark: '#8e2f22', light: '#ffd08a', glyph: '✦' },
  frost:  { name: 'Frost',   color: '#7fd8ef', dark: '#28617f', light: '#d5f7ff', glyph: '❄' },
  earth:  { name: 'Earth',   color: '#d9ae6b', dark: '#73532d', light: '#f5dfb0', glyph: '⬢' },
  shadow: { name: 'Shadow',  color: '#b48ae0', dark: '#4a2a68', light: '#e3c9ff', glyph: '☾' },
  light:  { name: 'Light',   color: '#ffe27a', dark: '#96702a', light: '#fff8cc', glyph: '☀' },
  storm:  { name: 'Storm',   color: '#9db9ff', dark: '#39447f', light: '#dce6ff', glyph: '⚡' },
  dragon: { name: 'Dragon',  color: '#e8848c', dark: '#7b2d3a', light: '#ffc2c6', glyph: '✧' },
}

export const ATTACK_CHART = {
  nature: { earth: 2, storm: 2, flame: 0.5, frost: 0.5 },
  flame:  { nature: 2, frost: 2, earth: 0.5, dragon: 0.5 },
  frost:  { nature: 2, earth: 2, flame: 0.5, storm: 0.5 },
  earth:  { flame: 2, storm: 2, nature: 0.5, frost: 0.5 },
  storm:  { frost: 2, light: 2, earth: 0.5, nature: 0.5 },
  shadow: { light: 2, storm: 2, nature: 0.5, shadow: 0.5 },
  light:  { shadow: 2, dragon: 2, storm: 0.5, light: 0.5 },
  dragon: { light: 2, nature: 0.5, flame: 0.5, frost: 0.5, earth: 0.5, storm: 0.5, shadow: 0.5, dragon: 0.5 },
  none:   {},
}

export function effectiveness(attackElement, defendElement) {
  if (!attackElement || attackElement === 'none') return 1
  const row = ATTACK_CHART[attackElement]
  return row && row[defendElement] ? row[defendElement] : 1
}

export function effectivenessLabel(mult) {
  if (mult >= 2) return { text: 'Super effective!', cls: 'eff-super' }
  if (mult <= 0.5) return { text: 'Not very effective…', cls: 'eff-weak' }
  return null
}

export const RARITY = {
  common:    { name: 'Common',    color: '#b9c4cf', catch: 0.58, weight: 44, xp: 1 },
  uncommon:  { name: 'Uncommon',  color: '#78d9a4', catch: 0.44, weight: 24, xp: 1.25 },
  rare:      { name: 'Rare',      color: '#7fb8ff', catch: 0.3,  weight: 13, xp: 1.6 },
  epic:      { name: 'Epic',      color: '#c99bff', catch: 0.17, weight: 5,  xp: 2.1 },
  legendary: { name: 'Legendary', color: '#ffd36e', catch: 0.075, weight: 1, xp: 3 },
}

export const STATUS = {
  burn:      { name: 'Burn',      color: '#ff8a4c', glyph: '🔥', tick: 1 / 16, capture: 1.25 },
  poison:    { name: 'Poison',    color: '#c084fc', glyph: '☠', tick: 1 / 12, capture: 1.3 },
  sleep:     { name: 'Sleep',     color: '#9db9ff', glyph: 'zZ', tick: 0, capture: 1.75 },
  freeze:    { name: 'Freeze',    color: '#7fd8ef', glyph: '❄', tick: 0, capture: 1.8 },
  paralysis: { name: 'Paralysis', color: '#ffe27a', glyph: '⚡', tick: 0, capture: 1.45 },
}

export const STAT_LABELS = {
  hp: 'HP', atk: 'Attack', def: 'Defense', spa: 'Sp. Atk', spd: 'Sp. Def', spe: 'Speed',
}

export const STAT_ORDER = ['hp', 'atk', 'def', 'spa', 'spd', 'spe']

// Small shared utilities: deterministic RNG, math, formatting, tiny DOM helpers.

export function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function hashString(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

export function hash2(x, y, seed = 0) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 2246822519)
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296
}

export const clamp = (v, min, max) => Math.max(min, Math.min(max, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1)
export const pick = (arr, rng = Math.random) => arr[Math.floor(rng() * arr.length)]
export const uid = (prefix = 'id') => `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`

export function weightedPick(entries, rng = Math.random) {
  const total = entries.reduce((s, e) => s + e.weight, 0)
  let roll = rng() * total
  for (const e of entries) { roll -= e.weight; if (roll <= 0) return e }
  return entries[entries.length - 1]
}

export function shuffle(arr, rng = Math.random) {
  const out = arr.slice()
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1)); [out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

export function formatTime(minutes) {
  const m = ((minutes % 1440) + 1440) % 1440
  const h = Math.floor(m / 60)
  const mm = Math.floor(m % 60)
  return `${String(h).padStart(2, '0')}:${String(mm).padStart(2, '0')}`
}

export function isNight(minutes) {
  const h = Math.floor((((minutes % 1440) + 1440) % 1440) / 60)
  return h >= 20 || h < 6
}

export function timeOfDay(minutes) {
  const h = Math.floor((((minutes % 1440) + 1440) % 1440) / 60)
  if (h < 5) return 'Night'
  if (h < 8) return 'Dawn'
  if (h < 17) return 'Day'
  if (h < 20) return 'Dusk'
  return 'Night'
}

export function roman(n) {
  return ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'][n] || String(n)
}

export function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag)
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') node.className = v
    else if (k === 'html') node.innerHTML = v
    else if (k.startsWith('data-') || k === 'title') node.setAttribute(k, v)
    else if (k === 'style' && typeof v === 'object') Object.assign(node.style, v)
    else node[k] = v
  }
  for (const child of [].concat(children)) {
    if (child == null) continue
    node.append(child.nodeType ? child : document.createTextNode(String(child)))
  }
  return node
}

export function titleCase(str) {
  return str.replace(/(^|\s|-)\w/g, c => c.toUpperCase())
}

export function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms))
}

export function randomInt(min, max, rng = Math.random) {
  return Math.floor(rng() * (max - min + 1)) + min
}

// Monster instance logic: creation, stats, experience, evolution, eggs, healing.

import { getMonster, MONSTER_LIST, baseSpeciesId } from '../data/monsters.js'
import { getSkill } from '../data/skills.js'
import { getPassive } from '../data/passives.js'
import { PERSONALITIES, PERSONALITY_IDS } from '../data/personalities.js'
import { clamp, uid, pick, randomInt } from '../core/utils.js'

export const MAX_LEVEL = 60
export const MAX_PARTY = 6
export const MAX_MOVES = 4

export function xpNeed(level) {
  return Math.floor(28 * Math.pow(level, 1.38) + 18)
}

export function trainerXpNeed(level) {
  return Math.floor(120 * Math.pow(level, 1.5))
}

export function statsOf(monster) {
  const sp = getMonster(monster.speciesId)
  const level = monster.level
  const pers = PERSONALITIES[monster.personality] || PERSONALITIES.hardy
  const passive = getPassive(sp.passive)
  const stats = {}
  for (const key of ['hp', 'atk', 'def', 'spa', 'spd', 'spe']) {
    const base = sp.base[key]
    let val = key === 'hp'
      ? Math.floor(base * (level + 10) / 45) + level + 12
      : Math.floor(base * (level + 8) / 50) + 5
    if (key !== 'hp') {
      if (pers.plus === key) val *= 1.1
      if (pers.minus === key) val *= 0.9
      if (passive.kind === 'statBoost' && passive.stat === key) val *= passive.value
    }
    stats[key] = Math.max(1, Math.floor(val))
  }
  return stats
}

export function maxHpOf(monster) {
  return statsOf(monster).hp
}

export function xpProgress(monster) {
  const need = xpNeed(monster.level)
  return { current: monster.xp, need, pct: clamp(monster.xp / need, 0, 1) }
}

function learnsetAt(speciesId, level) {
  const sp = getMonster(speciesId)
  return sp.learnset.filter(([lvl]) => lvl <= level).map(([, id]) => id)
}

function unique(arr) { return [...new Set(arr)] }

function pickInitialMoves(learned) {
  const damaging = learned.filter(id => getSkill(id).power > 0)
  let moves = learned.slice(-MAX_MOVES)
  if (!moves.some(id => getSkill(id).power > 0) && damaging.length) moves[moves.length - 1] = damaging[damaging.length - 1]
  if (moves.length === 0) moves = ['tackle']
  return unique(moves).slice(-MAX_MOVES)
}

export function createMonster(speciesId, level = 5, opts = {}) {
  const sp = getMonster(speciesId)
  const lv = clamp(Math.round(level), 1, MAX_LEVEL)
  const learned = unique([...learnsetAt(speciesId, lv), ...(opts.extraMoves || [])])
  const moves = (opts.moves || pickInitialMoves(learned)).filter(id => id in { ...Object.fromEntries(learned.map(l => [l, 1])) } || opts.moves)
    .slice(0, MAX_MOVES)
  const personality = opts.personality || pick(PERSONALITY_IDS)
  const monster = {
    uid: opts.uid || uid('mon'),
    speciesId,
    nickname: opts.nickname || sp.name,
    nicknameCustom: !!opts.nickname,
    level: lv,
    xp: 0,
    personality,
    friendship: opts.friendship ?? 35,
    learned,
    moves: moves.length ? moves : pickInitialMoves(learned),
    status: null,
    statusTurns: 0,
    isEgg: false,
    caughtAt: opts.caughtAt || null,
    caughtBiome: opts.caughtBiome || sp.biome,
    caughtNight: !!opts.caughtNight,
    metLevel: lv,
  }
  monster.hp = maxHpOf(monster)
  return monster
}

export function createEgg(parentA, parentB) {
  const speciesId = baseSpeciesId(parentA.speciesId)
  const sp = getMonster(speciesId)
  const inherited = unique([
    ...parentA.moves.slice(0, 2).filter(id => getSkill(id).power > 0),
    ...parentB.moves.slice(0, 1).filter(id => getSkill(id).power > 0),
  ]).slice(0, 3)
  const egg = {
    uid: uid('egg'),
    speciesId,
    nickname: 'Mystery Egg',
    nicknameCustom: true,
    level: 1,
    xp: 0,
    personality: Math.random() < 0.5 ? parentA.personality : parentB.personality,
    friendship: 60,
    learned: ['tackle', ...inherited],
    moves: ['tackle', ...inherited].slice(0, MAX_MOVES),
    status: null,
    statusTurns: 0,
    isEgg: true,
    hatchSteps: 120 + Math.max(parentA.level, parentB.level) * 2,
    hatchMax: 120 + Math.max(parentA.level, parentB.level) * 2,
    parentSpecies: [parentA.speciesId, parentB.speciesId],
    caughtAt: null,
    caughtBiome: sp.biome,
  }
  egg.hp = 1
  return egg
}

export function hatchEgg(egg) {
  const sp = getMonster(egg.speciesId)
  const lv = 5
  const learned = unique([...egg.learned, ...learnsetAt(egg.speciesId, lv)])
  const monster = {
    ...egg,
    isEgg: false,
    level: lv,
    nickname: sp.name,
    nicknameCustom: false,
    learned,
    moves: unique([...egg.moves, ...pickInitialMoves(learned)]).slice(0, MAX_MOVES),
    hatchSteps: 0,
  }
  monster.hp = maxHpOf(monster)
  return monster
}

export function healMonster(monster) {
  monster.hp = maxHpOf(monster)
  monster.status = null
  monster.statusTurns = 0
}

export function healParty(state) {
  for (const m of state.party) if (!m.isEgg) healMonster(m)
  for (const m of state.storage) if (!m.isEgg) { m.hp = maxHpOf(m); m.status = null }
}

export function syncLearned(monster) {
  const known = new Set(monster.learned)
  const newSkills = []
  for (const id of learnsetAt(monster.speciesId, monster.level)) {
    if (!known.has(id)) { known.add(id); monster.learned.push(id); newSkills.push(id) }
  }
  for (const id of newSkills) {
    if (monster.moves.length < MAX_MOVES) monster.moves.push(id)
    else {
      // Auto-upgrade only if the new skill is clearly stronger and replaces a weaker slot.
      const power = getSkill(id).power
      const weakest = monster.moves.reduce((a, b) => (getSkill(a).power <= getSkill(b).power ? a : b))
      if (power > getSkill(weakest).power + 10) monster.moves[monster.moves.indexOf(weakest)] = id
    }
  }
  return newSkills
}

export function gainXp(monster, amount, opts = {}) {
  if (monster.isEgg) return { levels: [], newSkills: [] }
  const result = { levels: [], newSkills: [], xp: amount }
  if (monster.level >= MAX_LEVEL) return result
  monster.xp += amount
  let guard = 0
  while (monster.xp >= xpNeed(monster.level) && monster.level < MAX_LEVEL && guard++ < 30) {
    monster.xp -= xpNeed(monster.level)
    monster.level++
    result.levels.push(monster.level)
    const beforeMoves = new Set(monster.moves)
    for (const id of syncLearned(monster)) {
      if (!beforeMoves.has(id)) result.newSkills.push({ id, equipped: monster.moves.includes(id) })
    }
    monster.hp = Math.min(maxHpOf(monster), monster.hp + Math.floor(maxHpOf(monster) * 0.06))
  }
  if (monster.level >= MAX_LEVEL) monster.xp = 0
  return result
}

export function addFriendship(monster, amount) {
  monster.friendship = clamp(monster.friendship + amount, 0, 100)
}

export function evolutionCandidates(monster, context = {}) {
  if (monster.isEgg) return []
  const sp = getMonster(monster.speciesId)
  return (sp.evolutions || []).filter(evo => {
    if (evo.type === 'item') {
      return context.itemId ? evo.item === context.itemId && monster.level >= (evo.level || 1) : false
    }
    if (monster.level < (evo.level || 1)) return false
    if (evo.type === 'level') return true
    if (evo.type === 'friendship') return monster.friendship >= (evo.friendship ?? 70)
    if (evo.type === 'location') return !!context.biome && context.biome === evo.biome
    return false
  })
}

export function performEvolution(monster, evo) {
  const oldSpecies = getMonster(monster.speciesId)
  const newSpecies = getMonster(evo.to)
  const ratio = monster.hp / Math.max(1, maxHpOf(monster))
  monster.speciesId = evo.to
  if (!monster.nicknameCustom) monster.nickname = newSpecies.name
  monster.friendship = clamp(monster.friendship + 5, 0, 100)
  const newSkills = syncLearned(monster)
  monster.hp = Math.max(1, Math.round(maxHpOf(monster) * Math.min(1, ratio + 0.15)))
  return { from: oldSpecies, to: newSpecies, newSkills }
}

export function evolveMonster(monster, evo, state) {
  const result = performEvolution(monster, evo)
  if (state) {
    state.stats.evolutions = (state.stats.evolutions || 0) + 1
  }
  return result
}

export function updateMoves(monster, moves) {
  const valid = moves.filter(id => monster.learned.includes(id)).slice(0, MAX_MOVES)
  if (valid.length) monster.moves = valid
}

export function knownMovePool(monster) {
  return unique([...monster.learned, ...monster.moves]).map(id => getSkill(id))
}

export function partyLead(state) {
  return state.party.find(m => !m.isEgg && m.hp > 0) || state.party.find(m => !m.isEgg) || null
}

export function partyIsWiped(state) {
  return !state.party.some(m => !m.isEgg && m.hp > 0) && state.party.some(m => !m.isEgg)
}

export function speciesFamily(speciesId) {
  const sp = getMonster(speciesId)
  const members = MONSTER_LIST.filter(m => m.id === speciesId || (m.evolutions || []).some(e => e.to === speciesId))
  return { sp, members }
}

export function randomWildStats(speciesId, level) {
  const m = createMonster(speciesId, level)
  m.hp = maxHpOf(m)
  return m
}

export { PERSONALITIES }

