export function npcSprite(role = 'lore', dir = 'down', frame = 0) {
  const key = `${role}|${dir}|${frame}`
  if (npcCache.has(key)) return npcCache.get(key)
  const palette = CLOTHES[role] || CLOTHES.lore || CLOTHES.elder
  const canvas = document.createElement('canvas')
  canvas.width = 18; canvas.height = 26
  const c = canvas.getContext('2d')
  c.imageSmoothingEnabled = false
  drawHumanoid(c, palette, dir, frame, role)
  npcCache.set(key, canvas)
  return canvas
}

export function playerSprite(dir = 'down', frame = 0) {
  return npcSprite('player', dir, frame)
}

function drawHumanoid(c, p, dir, frame, role) {
  const moving = frame === 1
  const bob = moving ? 0 : 0
  // shadow
  ellipse(c, 9, 24, 6, 2, 'rgba(0,0,0,0.25)')
  // legs
  if (dir === 'left' || dir === 'right') {
    rect(c, 7, 20 + bob, 3, 4, p.coat2)
    rect(c, 10, 20 + bob, 3, 4, p.coat2)
    rect(c, moving ? 6 : 7, 23 + bob, 4, 2, p.boots)
    rect(c, moving ? 10 : 11, 23 + bob, 4, 2, p.boots)
  } else {
    rect(c, 6, 20 + bob, 3, 4, p.coat2)
    rect(c, 10, 20 + bob, 3, 4, p.coat2)
    rect(c, 6, 23 + bob, 4, 2, p.boots)
    rect(c, 10, 23 + bob, 4, 2, p.boots)
  }
  // coat
  rect(c, 5, 13 + bob, 9, 9, p.coat2)
  rect(c, 6, 13 + bob, 7, 7, p.coat)
  rect(c, 8, 14 + bob, 2, 7, p.trim)
  // arms
  rect(c, 4, 15 + bob, 2, 5, p.coat)
  rect(c, 13, 15 + bob, 2, 5, p.coat)
  rect(c, 4, 19 + bob, 2, 2, p.skin)
  rect(c, 13, 19 + bob, 2, 2, p.skin)
  // head
  rect(c, 6, 7 + bob, 7, 7, p.skin)
  // hair / hat
  if (role === 'witch') {
    rect(c, 5, 4 + bob, 9, 2, p.hat)
    tri(c, 6, 5 + bob, 9, 0 + bob, 12, 5 + bob, p.hat)
  } else if (role === 'healer') {
    rect(c, 5, 5 + bob, 9, 3, p.hat)
    rect(c, 8, 4 + bob, 3, 2, p.trim)
  } else if (role === 'player' || role === 'trainer') {
    rect(c, 5, 5 + bob, 9, 3, p.hat)
    rect(c, 4, 7 + bob, 11, 2, p.hat)
  } else if (role === 'spirit') {
    rect(c, 5, 5 + bob, 9, 2, p.hat)
  } else {
    rect(c, 5, 5 + bob, 9, 2, p.hair)
    rect(c, 4, 7 + bob, 2, 3, p.hair)
    rect(c, 13, 7 + bob, 2, 3, p.hair)
  }
  // face
  if (dir !== 'up') {
    rect(c, 7, 9 + bob, 1, 2, '#2a1e18')
    rect(c, 11, 9 + bob, 1, 2, '#2a1e18')
  } else {
    rect(c, 6, 8 + bob, 7, 4, p.hair)
  }
  // scarf/satchel
  rect(c, 5, 12 + bob, 9, 2, p.trim)
  if (role === 'merchant') rect(c, 12, 16 + bob, 3, 3, p.boots)
  if (role === 'player') rect(c, 4, 16 + bob, 3, 3, p.boots)
}

export function flipCanvas(canvas) {
  const out = document.createElement('canvas')
  out.width = canvas.width; out.height = canvas.height
  const c = out.getContext('2d')
  c.imageSmoothingEnabled = false
  c.translate(canvas.width, 0); c.scale(-1, 1)
  c.drawImage(canvas, 0, 0)
  return out
}

export function elementPalette(element) {
  const p = PALETTES[element] || PALETTES.none
  return { ...p, meta: ELEMENTS[element] || ELEMENTS.none }
}

// World generation and runtime simulation.
// A single 176×132 tile continent, generated deterministically, with organic biome
// regions, roads and bridges, towns, tall decorations, resources, NPCs and spawning.

import { BIOMES, BIOME_LIST, BIOME_ORDER } from '../data/biomes.js'
import { MONSTER_LIST, getMonster } from '../data/monsters.js'
import { RARITY } from '../data/elements.js'
import { npcsForBiome } from '../data/npcs.js'
import { createMonster, maxHpOf } from '../game/monsters.js'
import { markSeen, visitBiome, recordGather, advanceTime } from '../game/state.js'
import { emit } from '../core/events.js'
import { hash2, mulberry32, clamp, dist, pick, randomInt, isNight } from '../core/utils.js'

export const TILE = 16
export const MAP_W = 176
export const MAP_H = 132
export const WORLD_W = MAP_W * TILE
export const WORLD_H = MAP_H * TILE

const T = { GROUND: 0, PATH: 1, WATER: 2, LAVA: 3, BRIDGE: 4, PLAZA: 5, OCEAN: 6, ICE: 7, ASH: 8 }

const LINKS = [
  ['forest', 'swamp'], ['swamp', 'desert'], ['desert', 'frozen'],
  ['frozen', 'volcano'], ['volcano', 'dragon'], ['dragon', 'ruins'],
  ['ruins', 'forest'],
  ['celestial', 'swamp'], ['celestial', 'desert'], ['celestial', 'ruins'], ['celestial', 'volcano'],
]

const TALL = {
  tree: { solid: true, h: 34 }, deadTree: { solid: true, h: 30 }, pine: { solid: true, h: 32 },
  cactus: { solid: true, h: 22 }, crystal: { solid: true, h: 22 }, rock: { solid: true, h: 10 },
  iceRock: { solid: true, h: 12 }, obsidian: { solid: true, h: 16 }, lavaRock: { solid: true, h: 10 },
  pillar: { solid: true, h: 30 }, obelisk: { solid: true, h: 36 }, spike: { solid: true, h: 26 },
  bone: { solid: true, h: 12 }, urn: { solid: true, h: 12 }, house: { solid: true, h: 42 },
  cairn: { solid: true, h: 12 }, gear: { solid: false, h: 10 }, forge: { solid: true, h: 24 },
  bush: { solid: false, h: 8 }, flowers: { solid: false, h: 3 }, fern: { solid: false, h: 8 },
  stump: { solid: true, h: 8 }, reed: { solid: false, h: 12 }, mushroom: { solid: false, h: 7 },
  wisp: { solid: false, h: 5 }, skull: { solid: false, h: 5 }, snowdrift: { solid: false, h: 5 },
  spring: { solid: false, h: 3 }, ashpile: { solid: false, h: 5 }, rubble: { solid: false, h: 4 },
  stairs: { solid: false, h: 5 }, nest: { solid: false, h: 5 }, banner: { solid: true, h: 28 },
  starflower: { solid: false, h: 7 }, cloudstone: { solid: true, h: 18 }, lantern: { solid: true, h: 20 },
  vent: { solid: true, h: 8 },
}

export class GameWorld {
  constructor(state) {
    this.state = state
    this.rng = mulberry32(20260413)
    this.biomeGrid = new Uint8Array(MAP_W * MAP_H)
    this.terrainGrid = new Uint8Array(MAP_W * MAP_H).fill(T.GROUND)
    this.solidGrid = new Uint8Array(MAP_W * MAP_H)
    this.variantGrid = new Uint8Array(MAP_W * MAP_H)
    this.decos = []
    this.decoChunks = new Map()
    this.npcs = []
    this.wilds = []
    this.resources = []
    this.bosses = []
    this.mythics = []
    this.towns = {}
    this.bossPoints = {}
    this.mythicPoints = {}
    this.player = { x: 0, y: 0, dir: 'down' }
    this.encounterCooldown = 2
    this.time = 0
    this.spawnTimers = {}
    this.stepAccumulator = 0
    this.currentBiome = 'forest'
    this.generate()
    this.spawnAll()
  }

  // ── generation ────────────────────────────────────────────────────────────
  generate() {
    this.assignBiomes()
    this.carveTownsAndArenas()
    this.carveRoads()
    this.addWaterFeatures()
    this.placeBuildings()
    this.addDecorations()
    this.bakeGround()
    this.buildMinimap()
  }

  assignBiomes() {
    const centers = BIOME_LIST.map(b => ({ id: b.id, x: b.center[0], y: b.center[1], index: BIOME_ORDER.indexOf(b.id) }))
    const celestial = BIOMES.celestial.center
    for (let y = 0; y < MAP_H; y++) {
      for (let x = 0; x < MAP_W; x++) {
        const i = y * MAP_W + x
        const coast = hash2(x, y, 31) * 2.5
        const edge = Math.min(x, y, MAP_W - 1 - x, MAP_H - 1 - y)
        if (edge < 4 + coast) { this.terrainGrid[i] = T.OCEAN; this.biomeGrid[i] = 8; this.solidGrid[i] = 1; continue }

        const dc = Math.hypot(x - celestial[0], y - celestial[1])
        let biome
        if (dc < 20.5) biome = 'celestial'
        else {
          let best = Infinity
          for (const c of centers) {
            const warp = (hash2(Math.floor(x / 7), Math.floor(y / 7), 101 + c.index) - 0.5) * 12
            const d = Math.hypot(x - c.x, y - c.y) + warp
            if (d < best) { best = d; biome = c.id }
          }
        }
        const bIdx = BIOME_ORDER.indexOf(biome)
        this.biomeGrid[i] = bIdx
        this.variantGrid[i] = Math.floor(hash2(x, y, 13) * 4)

        if (biome === 'celestial' && dc >= 12.5) {
          this.terrainGrid[i] = T.WATER; this.solidGrid[i] = 1
        } else if (biome === 'swamp' && hash2(x, y, 71) < 0.035 && dc > 21) {
          this.terrainGrid[i] = T.WATER; this.solidGrid[i] = 1
        }
      }
    }
  }

  carveTownsAndArenas() {
    for (const b of BIOME_LIST) {
      const tx = b.center[0] + b.town.offset[0]
      const ty = b.center[1] + b.town.offset[1]
      this.towns[b.id] = { x: tx, y: ty, name: b.town.name }
      this.carveCircle(tx, ty, 9, T.PLAZA)
      const bx = clamp(b.center[0] + b.boss.offset[0], 6, MAP_W - 7)
      const by = clamp(b.center[1] + b.boss.offset[1], 6, MAP_H - 7)
      this.bossPoints[b.id] = { x: bx, y: by }
      this.carveCircle(bx, by, 7, T.PLAZA)
      const mx = clamp(b.center[0] + b.mythic.offset[0], 6, MAP_W - 7)
      const my = clamp(b.center[1] + b.mythic.offset[1], 6, MAP_H - 7)
      this.mythicPoints[b.id] = { x: mx, y: my }
      this.carveCircle(mx, my, 4, T.GROUND)
    }
    // clear a generous landing area around the island sanctum
    const c = BIOMES.celestial.center
    this.carveCircle(c[0], c[1], 8, T.PLAZA)
  }

  carveCircle(cx, cy, r, terrain) {
    for (let y = Math.max(1, cy - r); y <= Math.min(MAP_H - 2, cy + r); y++) {
      for (let x = Math.max(1, cx - r); x <= Math.min(MAP_W - 2, cx + r); x++) {
        if (Math.hypot(x - cx, y - cy) > r) continue
        this.setTerrain(x, y, terrain, false)
      }
    }
  }

  carveRoads() {
    for (const [a, b] of LINKS) {
      const ca = BIOMES[a].center, cb = BIOMES[b].center
      this.carveRoad(ca[0], ca[1], cb[0], cb[1])
    }
    // Short connectors from ring roads to each town square.
    for (const b of BIOME_LIST) {
      const t = this.towns[b.id]
      this.carveLine(t.x, t.y, b.center[0], b.center[1], 3)
      const boss = this.bossPoints[b.id]
      this.carveLine(t.x, t.y, boss.x, boss.y, 2)
    }
  }

  carveRoad(x1, y1, x2, y2, width = 3) {
    const len = Math.hypot(x2 - x1, y2 - y1)
    const steps = Math.ceil(len * 2)
    for (let i = 0; i <= steps; i++) {
      const t = i / steps
      const wob = Math.sin(t * Math.PI * 6 + x1) * 2.2
      const nx = -(y2 - y1) / (len || 1), ny = (x2 - x1) / (len || 1)
      const x = Math.round(x1 + (x2 - x1) * t + nx * wob)
      const y = Math.round(y1 + (y2 - y1) * t + ny * wob)
      for (let dy = -Math.floor(width / 2); dy <= Math.floor(width / 2); dy++) {
        for (let dx = -Math.floor(width / 2); dx <= Math.floor(width / 2); dx++) {
          const tx = x + dx, ty = y + dy
          if (tx < 3 || ty < 3 || tx >= MAP_W - 3 || ty >= MAP_H - 3) continue
          const i2 = ty * MAP_W + tx
          const existing = this.terrainGrid[i2]
          if (existing === T.WATER || existing === T.OCEAN) this.terrainGrid[i2] = T.BRIDGE
          else if (existing === T.LAVA) this.terrainGrid[i2] = T.BRIDGE
          else if (existing !== T.PLAZA) this.terrainGrid[i2] = T.PATH
          this.solidGrid[i2] = 0
        }
      }
    }
  }

  carveLine(x1, y1, x2, y2, width) {
    this.carveRoad(x1, y1, x2, y2, width)
  }

  addWaterFeatures() {
    const rng = this.rng
    const features = [
      { biome: 'forest', terrain: T.WATER, count: 9, radius: [1, 3] },
      { biome: 'frozen', terrain: T.ICE, count: 8, radius: [1, 3] },
      { biome: 'volcano', terrain: T.LAVA, count: 10, radius: [1, 2] },
      { biome: 'desert', terrain: T.WATER, count: 3, radius: [1, 2] },
      { biome: 'swamp', terrain: T.WATER, count: 8, radius: [1, 3] },
    ]
    for (const f of features) {
      const b = BIOMES[f.biome]
      let placed = 0, attempts = 0
      while (placed < f.count && attempts++ < 100) {
        const x = b.center[0] + Math.round((rng() - 0.5) * 45)
        const y = b.center[1] + Math.round((rng() - 0.5) * 40)
        if (x < 10 || y < 10 || x >= MAP_W - 10 || y >= MAP_H - 10) continue
        if (BIOME_ORDER[this.biomeGrid[y * MAP_W + x]] !== f.biome) continue
        if (this.nearTown(x, y, 13) || this.nearBoss(x, y, 10)) continue
        if (this.nearPath(x, y, 2)) continue
        this.carveCircle(x, y, randomInt(f.radius[0], f.radius[1], rng), f.terrain)
        if (f.terrain === T.LAVA) this.carveCircle(x, y, 1, T.ASH)
        placed++
      }
    }
  }

  setTerrain(x, y, terrain, solid = null) {
    if (x < 1 || y < 1 || x >= MAP_W - 1 || y >= MAP_H - 1) return
    const i = y * MAP_W + x
    this.terrainGrid[i] = terrain
    if (solid === true) this.solidGrid[i] = 1
    else if (solid === false) this.solidGrid[i] = 0
    else this.solidGrid[i] = (terrain === T.WATER || terrain === T.LAVA || terrain === T.OCEAN) ? 1 : 0
  }

  nearTown(x, y, r) {
    return Object.values(this.towns).some(t => Math.hypot(t.x - x, t.y - y) < r)
  }
  nearBoss(x, y, r) {
    return Object.values(this.bossPoints).some(t => Math.hypot(t.x - x, t.y - y) < r)
  }
  nearPath(x, y, r) {
    for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
      const tx = x + dx, ty = y + dy
      if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) continue
      if (this.terrainGrid[ty * MAP_W + tx] === T.PATH) return true
    }
    return false
  }

  placeBuildings() {
    for (const b of BIOME_LIST) {
      const town = this.towns[b.id]
      const spots = [[-6, -5, 0], [5, -5, 1], [-7, 4, 2], [6, 5, 3]]
      for (const [dx, dy, variant] of spots) {
        const x = town.x + dx, y = town.y + dy
        if (x < 4 || y < 4 || x >= MAP_W - 5 || y >= MAP_H - 6) continue
        this.addDeco('house', x, y, b.id, variant, true, 3)
        for (let yy = y; yy < y + 2; yy++) for (let xx = x - 1; xx <= x + 1; xx++) this.solidGrid[yy * MAP_W + xx] = 1
        this.setTerrain(x, y, T.PLAZA, false)
      }
      // Town lanterns / signposts
      this.addDeco(b.id === 'celestial' ? 'lantern' : 'banner', town.x, town.y - 3, b.id, 0, true, 1)
      for (const [dx, dy] of [[-2, -6], [2, -6], [-9, 0], [8, 0]]) {
        const x = town.x + dx, y = town.y + dy
        if (!this.isSolidTile(x, y)) this.addDeco('lantern', x, y, b.id, 1, true, 1)
      }
    }
  }

  addDeco(type, x, y, biome, variant = 0, force = false, solidWidth = 1) {
    const info = TALL[type]
    if (!info) return
    this.decos.push({ type, x, y, biome, variant, h: info.h, solidWidth })
    if (info.solid || force) {
      for (let dy = 0; dy < 2; dy++) {
        for (let dx = -Math.floor(solidWidth / 2); dx <= Math.floor(solidWidth / 2); dx++) {
          const tx = x + dx, ty = y + dy
          if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) continue
          this.solidGrid[ty * MAP_W + tx] = 1
        }
      }
    }
    const chunkKey = `${Math.floor(x / 12)},${Math.floor(y / 12)}`
    if (!this.decoChunks.has(chunkKey)) this.decoChunks.set(chunkKey, [])
    this.decoChunks.get(chunkKey).push(this.decos[this.decos.length - 1])
  }

  addDecorations() {
    const rng = mulberry32(77123)
    for (let y = 7; y < MAP_H - 7; y++) {
      for (let x = 7; x < MAP_W - 7; x++) {
        const i = y * MAP_W + x
        if (this.solidGrid[i]) continue
        const terrain = this.terrainGrid[i]
        if (terrain !== T.GROUND && terrain !== T.ASH && terrain !== T.ICE) continue
        if (this.nearTown(x, y, 10) || this.nearBoss(x, y, 8)) continue
        if (this.nearPath(x, y, 1)) continue
        if (Object.values(this.towns).some(t => Math.hypot(t.x - x, t.y - y) < 14)) continue
        const biome = BIOME_ORDER[this.biomeGrid[i]]
        const density = biome === 'forest' ? 0.16 : biome === 'swamp' ? 0.13 : biome === 'frozen' ? 0.12 : biome === 'dragon' ? 0.1 : biome === 'ruins' ? 0.08 : 0.07
        if (rng() > density) continue
        // Avoid clumping directly adjacent to other tall decos.
        let near = false
        for (let dy = -1; dy <= 1 && !near; dy++) for (let dx = -1; dx <= 1; dx++) {
          const other = this.decos.find(d => d.x === x + dx && d.y === y + dy)
          if (other && other.h > 16) { near = true; break }
        }
        if (near) continue
        const list = BIOMES[biome].deco
        let type = pick(list, rng)
        if (type === 'wisp' || type === 'starflower' || type === 'lantern') type = pick(list.filter(t => t !== type), rng) || type
        this.addDeco(type, x, y, biome, Math.floor(rng() * 4))
        if (TALL[type]?.solid) this.solidGrid[i] = 1
      }
    }
    // Boss arenas get ceremonial pillars / monoliths.
    for (const b of BIOME_LIST) {
      const p = this.bossPoints[b.id]
      for (let a = 0; a < 8; a++) {
        const ang = (a / 8) * Math.PI * 2
        const x = Math.round(p.x + Math.cos(ang) * 7)
        const y = Math.round(p.y + Math.sin(ang) * 6)
        if (x < 3 || y < 3 || x >= MAP_W - 3 || y >= MAP_H - 3) continue
        const type = b.id === 'forest' ? 'tree' : b.id === 'volcano' ? 'obsidian' : b.id === 'frozen' ? 'iceRock' : b.id === 'celestial' ? 'obelisk' : b.id === 'dragon' ? 'spike' : b.id === 'ruins' ? 'pillar' : b.id === 'desert' ? 'crystal' : 'deadTree'
        this.addDeco(type, x, y, b.id, a)
        this.solidGrid[y * MAP_W + x] = 1
      }
    }
  }

  isSolidTile(x, y) {
    if (x < 0 || y < 0 || x >= MAP_W || y >= MAP_H) return true
    return !!this.solidGrid[y * MAP_W + x]
  }

  // ── baked ground ──────────────────────────────────────────────────────────
  bakeGround() {
    const canvas = document.createElement('canvas')
    canvas.width = WORLD_W; canvas.height = WORLD_H
    const c = canvas.getContext('2d')
    c.imageSmoothingEnabled = false
    const pal = Object.fromEntries(BIOME_LIST.map(b => [b.id, b.palette]))
    for (let y = 0; y < MAP_H; y++) {
      for (let x = 0; x < MAP_W; x++) {
        const i = y * MAP_W + x
        const biome = BIOME_ORDER[this.biomeGrid[i]]
        const terrain = this.terrainGrid[i]
        const p = pal[biome] || pal.forest
        const px = x * TILE, py = y * TILE
        const v = this.variantGrid[i] + Math.floor(hash2(x, y, 3) * 4)
        let color
        if (terrain === T.OCEAN || terrain === T.WATER) {
          color = terrain === T.OCEAN ? '#204868' : p.water
          if (biome === 'frozen' && terrain === T.WATER) color = '#a9ddec'
        } else if (terrain === T.LAVA) {
          color = (v % 2) ? '#d6512c' : '#ef6a2e'
        } else if (terrain === T.ICE) {
          color = v % 2 ? '#a9d9e8' : '#c2e9f2'
        } else if (terrain === T.BRIDGE) {
          color = biome === 'celestial' ? '#cbbf98' : '#8a6a48'
        } else if (terrain === T.PATH) {
          color = v % 3 === 0 ? p.path2 : p.path
        } else if (terrain === T.PLAZA) {
          color = biome === 'celestial' ? '#ddd5b6' : (v % 2 ? '#b8a47e' : '#c4b18a')
        } else if (terrain === T.ASH) {
          color = v % 2 ? '#3b3130' : '#453938'
        } else {
          color = [p.ground, p.ground2, p.ground3, p.ground][v % 4]
        }
        c.fillStyle = color
        c.fillRect(px, py, TILE, TILE)

        // organic tile texture
        const seed = hash2(x, y, 57)
        if (terrain === T.GROUND) {
          if (seed < 0.35) {
            c.fillStyle = p.ground2
            c.fillRect(px + 3 + Math.floor(seed * 30) % 8, py + 4 + Math.floor(seed * 17) % 7, 3, 2)
          }
          if (seed > 0.9) {
            c.fillStyle = p.ground3
            c.fillRect(px + 7, py + 9, 4, 2)
          }
          if (biome === 'forest' && seed > 0.75) {
            c.fillStyle = '#7fcf6f'
            c.fillRect(px + 4, py + 11, 1, 2); c.fillStyle = '#a8e88c'; c.fillRect(px + 4, py + 10, 1, 1)
          }
          if (biome === 'desert' && seed > 0.6) {
            c.fillStyle = 'rgba(255,240,190,0.35)'; c.fillRect(px + 2, py + 6, 6, 1)
          }
          if (biome === 'celestial' && seed > 0.62) {
            c.fillStyle = 'rgba(255,248,190,0.5)'; c.fillRect(px + 5, py + 7, 2, 2)
          }
        }
        if ((terrain === T.OCEAN || terrain === T.WATER) && seed > 0.55) {
          c.fillStyle = terrain === T.OCEAN ? '#3b6c8c' : 'rgba(220,250,255,0.5)'
          const wx = px + 2 + Math.floor(seed * 9)
          c.fillRect(wx, py + 4 + Math.floor(seed * 10 % 6), 5, 1)
          c.fillRect(wx + 2, py + 9 + Math.floor(seed * 13 % 4), 4, 1)
        }
        if (terrain === T.LAVA) {
          c.fillStyle = '#ffcf6a'
          c.fillRect(px + 4, py + 6 + Math.floor(seed * 6), 5, 2)
          if (seed > 0.6) c.fillRect(px + 9, py + 2, 2, 3)
        }
        if (terrain === T.BRIDGE) {
          c.fillStyle = 'rgba(45,25,15,0.55)'
          for (let k = 0; k < 4; k++) c.fillRect(px, py + k * 4, TILE, 1)
          c.fillStyle = '#3f2a1c'
          c.fillRect(px, py, 1, TILE); c.fillRect(px + TILE - 1, py, 1, TILE)
        }
        if (terrain === T.PATH || terrain === T.PLAZA) {
          if (seed > 0.6) { c.fillStyle = 'rgba(80,60,40,0.35)'; c.fillRect(px + 3, py + 5, 2, 2); c.fillRect(px + 10, py + 11, 2, 1) }
          if (seed < 0.12) { c.fillStyle = 'rgba(255,245,210,0.35)'; c.fillRect(px + 8, py + 7, 1, 1) }
        }
        // shoreline edges
        if (terrain !== T.WATER && terrain !== T.OCEAN && terrain !== T.LAVA) {
          const above = this.terrainGrid[(y - 1) * MAP_W + x]
          if (above === T.WATER || above === T.OCEAN) { c.fillStyle = 'rgba(240,250,255,0.6)'; c.fillRect(px, py, TILE, 2) }
        }
      }
    }
    // Fine details on plaza: mosaic around town centre
    for (const t of Object.values(this.towns)) {
      const cx = t.x * TILE + 8, cy = t.y * TILE + 8
      c.strokeStyle = 'rgba(255,240,200,0.28)'
      c.lineWidth = 1
      c.beginPath(); c.arc(cx, cy, 5 * TILE, 0, Math.PI * 2); c.stroke()
      c.beginPath(); c.arc(cx, cy, 2.4 * TILE, 0, Math.PI * 2); c.stroke()
    }
    this.mapCanvas = canvas
  }

  buildMinimap() {
    const canvas = document.createElement('canvas')
    canvas.width = MAP_W; canvas.height = MAP_H
    const c = canvas.getContext('2d')
    for (let y = 0; y < MAP_H; y++) {
      for (let x = 0; x < MAP_W; x++) {
        const i = y * MAP_W + x
        const terrain = this.terrainGrid[i]
        const b = BIOMES[BIOME_ORDER[this.biomeGrid[i]]]
        let col = b.palette.ground
        if (terrain === T.OCEAN) col = '#1b3f5c'
        else if (terrain === T.WATER) col = '#356b8a'
        else if (terrain === T.LAVA) col = '#e2572c'
        else if (terrain === T.PATH) col = '#c9b48b'
        else if (terrain === T.PLAZA) col = '#e2d3ad'
        else if (terrain === T.BRIDGE) col = '#b09369'
        c.fillStyle = col
        c.fillRect(x, y, 1, 1)
      }
    }
    this.minimap = canvas
  }

  // ── entities ──────────────────────────────────────────────────────────────
  spawnAll() {
    this.spawnNpcs()
    this.spawnResources()
    this.spawnBosses()
    this.spawnMythics()
    for (const b of BIOME_LIST) {
      for (let i = 0; i < 3; i++) this.spawnWild(b.id)
    }
  }

  spawnNpcs() {
    for (const b of BIOME_LIST) {
      const town = this.towns[b.id]
      for (const def of npcsForBiome(b.id)) {
        const x = (town.x + def.offset[0]) * TILE + 8
        const y = (town.y + def.offset[1]) * TILE + 14
        this.npcs.push({ ...def, biome: b.id, x, y, home: { x, y }, dir: 'down', kind: 'npc' })
      }
    }
  }

  spawnResources() {
    const rng = mulberry32(9981)
    for (const b of BIOME_LIST) {
      let placed = 0, attempts = 0
      while (placed < 9 && attempts++ < 200) {
        const x = b.center[0] + Math.round((rng() - 0.5) * 38)
        const y = b.center[1] + Math.round((rng() - 0.5) * 32)
        if (x < 6 || y < 6 || x >= MAP_W - 6 || y >= MAP_H - 6) continue
        if (BIOME_ORDER[this.biomeGrid[y * MAP_W + x]] !== b.id) continue
        if (this.isSolidTile(x, y) || this.isSolidTile(x + 1, y)) continue
        if (this.nearTown(x, y, 11) || this.nearBoss(x, y, 9)) continue
        if (this.resources.some(r => Math.hypot(r.tx - x, r.ty - y) < 4)) continue
        const item = pick(b.resources, rng)
        this.resources.push({
          id: `res_${b.id}_${placed}`,
          item,
          biome: b.id,
          tx: x, ty: y,
          x: x * TILE + 8, y: y * TILE + 12,
          available: true,
          respawnAt: 0,
          kind: 'resource',
        })
        placed++
      }
    }
  }

  spawnBosses() {
    for (const b of BIOME_LIST) {
      if (this.state.flags.bosses[b.id]) continue
      const p = this.bossPoints[b.id]
      const monster = createMonster(b.boss.species, b.boss.level, { friendship: 50 })
      monster.hp = maxHpOf(monster)
      this.bosses.push({
        id: `boss_${b.id}`, kind: 'boss', biome: b.id,
        x: p.x * TILE + 8, y: p.y * TILE + 14,
        home: { x: p.x * TILE + 8, y: p.y * TILE + 14 },
        monster, speciesId: b.boss.species, bob: Math.random() * 6,
        name: `${b.boss.arena} Guardian`, arena: b.boss.arena,
      })
    }
  }

  spawnMythics() {
    for (const b of BIOME_LIST) {
      if (!this.state.flags.bosses[b.id] || this.state.flags.mythic[b.id]) continue
      const p = this.mythicPoints[b.id]
      const monster = createMonster(b.mythic.species, b.mythic.level, { friendship: 50 })
      monster.hp = maxHpOf(monster)
      this.mythics.push({
        id: `mythic_${b.id}`, kind: 'mythic', biome: b.id,
        x: p.x * TILE + 8, y: p.y * TILE + 14,
        home: { x: p.x * TILE + 8, y: p.y * TILE + 14 },
        monster, speciesId: b.mythic.species, bob: Math.random() * 6,
        name: `${getMonster(b.mythic.species).name} — Mythic`,
      })
    }
  }

  spawnTable(biome) {
    const night = isNight(this.state.time.minutes)
    const b = BIOMES[biome]
    const entries = []
    for (const m of MONSTER_LIST) {
      if (m.biome !== biome || m.wild === false) continue
      if (m.legendary) continue
      let weight = RARITY[m.rarity]?.weight || 10
      if (m.nocturnal) {
        if (!night) continue
        weight *= 2.4
      } else if (night) weight *= 0.72
      if (m.evolutions?.length) weight *= 0.8
      entries.push({ monster: m, weight })
    }
    if (!entries.length) entries.push({ monster: MONSTER_LIST.find(m => m.biome === biome), weight: 1 })
    return entries
  }

  spawnWild(biome, opts = {}) {
    const biomeDef = BIOMES[biome]
    const entries = this.spawnTable(biome)
    let total = entries.reduce((s, e) => s + e.weight, 0)
    let roll = Math.random() * total
    let chosen = entries[entries.length - 1]
    for (const e of entries) { roll -= e.weight; if (roll <= 0) { chosen = e; break } }
    const species = chosen.monster
    const level = opts.level ?? randomInt(biomeDef.level[0], biomeDef.level[1])
    const pos = this.findSpawnPosition(biome, opts.near)
    if (!pos) return null
    const monster = createMonster(species.id, level)
    monster.hp = maxHpOf(monster)
    markSeen(this.state, species.id)
    const wild = {
      id: `wild_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`,
      kind: 'wild', biome,
      x: pos.x * TILE + 8, y: pos.y * TILE + 12,
      home: { x: pos.x * TILE + 8, y: pos.y * TILE + 12 },
      speciesId: species.id, monster, level,
      vx: 0, vy: 0, moveTimer: Math.random() * 2, dir: Math.random() < 0.5 ? 'left' : 'right',
      bob: Math.random() * 6,
      spawnedAt: performance.now(),
    }
    this.wilds.push(wild)
    return wild
  }

  findSpawnPosition(biome, near = null) {
    const b = BIOMES[biome]
    for (let i = 0; i < 100; i++) {
      let tx, ty
      if (near) {
        tx = Math.floor(near.x / TILE) + randomInt(-8, 8)
        ty = Math.floor(near.y / TILE) + randomInt(-6, 6)
      } else {
        tx = b.center[0] + randomInt(-24, 24)
        ty = b.center[1] + randomInt(-20, 20)
      }
      if (tx < 5 || ty < 5 || tx >= MAP_W - 5 || ty >= MAP_H - 5) continue
      const i2 = ty * MAP_W + tx
      if (BIOME_ORDER[this.biomeGrid[i2]] !== biome) continue
      if (this.solidGrid[i2]) continue
      if (this.nearTown(tx, ty, 9)) continue
      const px = tx * TILE + 8, py = ty * TILE + 12
      if (this.player && Math.hypot(px - this.player.x, py - this.player.y) < 100) continue
      if (this.wilds.some(w => Math.hypot(w.x - px, w.y - py) < 40)) continue
      if (this.bosses.some(w => Math.hypot(w.x - px, w.y - py) < 30)) continue
      return { x: tx, y: ty }
    }
    return null
  }

  // ── runtime ───────────────────────────────────────────────────────────────
  placePlayerFromState() {
    const p = this.state.player
    if (p.x && p.y && this.canWalk(p.x, p.y)) {
      this.player.x = p.x; this.player.y = p.y
    } else {
      const t = this.towns[p.biome] || this.towns.forest
      this.player.x = t.x * TILE + 8
      this.player.y = (t.y + 3) * TILE + 10
    }
    this.player.dir = p.dir || 'down'
    this.currentBiome = this.biomeAtPixel(this.player.x, this.player.y)
  }

  biomeAtPixel(x, y) {
    const tx = clamp(Math.floor(x / TILE), 0, MAP_W - 1)
    const ty = clamp(Math.floor(y / TILE), 0, MAP_H - 1)
    return BIOME_ORDER[this.biomeGrid[ty * MAP_W + tx]]
  }

  biomeAtTile(tx, ty) {
    if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) return 'celestial'
    return BIOME_ORDER[this.biomeGrid[ty * MAP_W + tx]]
  }

  canWalk(x, y) {
    const hw = 5, hh = 4
    for (const [ox, oy] of [[-hw, -hh], [hw, -hh], [-hw, hh], [hw, hh]]) {
      if (this.isSolidTile(Math.floor((x + ox) / TILE), Math.floor((y + oy) / TILE))) return false
    }
    return true
  }

  movePlayer(dx, dy) {
    const p = this.player
    if (dx) {
      if (this.canWalk(p.x + dx, p.y)) p.x += dx
      else {
        // slide along blocked edges
        const step = Math.sign(dx) * 0.5
        for (let i = 0; i < Math.abs(dx) * 2; i++) { if (this.canWalk(p.x + step, p.y)) p.x += step; else break }
      }
    }
    if (dy) {
      if (this.canWalk(p.x, p.y + dy)) p.y += dy
      else {
        const step = Math.sign(dy) * 0.5
        for (let i = 0; i < Math.abs(dy) * 2; i++) { if (this.canWalk(p.x, p.y + step)) p.y += step; else break }
      }
    }
    if (dx || dy) {
      p.dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up')
      const moved = Math.hypot(dx, dy)
      this.onPlayerMoved(moved)
    }
  }

  onPlayerMoved(distance) {
    const st = this.state
    st.stats.steps += distance / TILE
    st.player.steps += distance / TILE
    this.stepAccumulator += distance / TILE
    if (this.stepAccumulator >= 1) {
      const steps = Math.floor(this.stepAccumulator)
      this.stepAccumulator -= steps
      this.advanceEggs(steps * 2)
    }
    const biome = this.biomeAtPixel(this.player.x, this.player.y)
    if (biome !== this.currentBiome) {
      this.currentBiome = biome
      st.player.biome = biome
      const first = !st.flags.visited[biome]
      visitBiome(st, biome)
      emit('toast', {
        title: first ? 'New Region Discovered' : BIOMES[biome].name,
        text: first ? BIOMES[biome].short + ' added to your map.' : '',
        icon: BIOMES[biome].icon,
        tone: 'region',
      })
      emit('biome-change', { biome })
    }
  }

  advanceEggs(steps) {
    for (const m of this.state.party) {
      if (!m.isEgg) continue
      m.hatchSteps = Math.max(0, m.hatchSteps - steps)
      if (m.hatchSteps <= 0 && !m.hatching) {
        m.hatching = true
        emit('egg-ready', { egg: m })
      }
    }
  }

  update(dt) {
    this.time += dt
    // advance game clock: one in-game minute per 1.5 real seconds
    this.clockAccumulator = (this.clockAccumulator || 0) + dt
    if (this.clockAccumulator > 1.5) {
      const mins = Math.floor(this.clockAccumulator / 1.5)
      this.clockAccumulator -= mins * 1.5
      advanceTime(this.state, mins * 0.9)
    }
    this.encounterCooldown = Math.max(0, this.encounterCooldown - dt)

    this.updateWilds(dt)
    this.updateSpawns(dt)
    this.updateResources()

    const near = this.nearestInteraction()
    const auto = this.closestWild(18)
    if (auto && this.encounterCooldown <= 0) {
      this.encounterCooldown = 1.5
      return { encounter: auto, near }
    }
    return { near }
  }

  updateWilds(dt) {
    const now = performance.now()
    for (const w of this.wilds) {
      w.bob += dt
      w.moveTimer -= dt
      if (w.moveTimer <= 0) {
        w.moveTimer = 1 + Math.random() * 2.6
        const ang = Math.random() * Math.PI * 2
        w.vx = Math.cos(ang) * (Math.random() < 0.35 ? 18 : 9)
        w.vy = Math.sin(ang) * (Math.random() < 0.35 ? 14 : 7)
        if (Math.abs(w.vx) > Math.abs(w.vy)) w.dir = w.vx > 0 ? 'right' : 'left'
      }
      // drift home if too far
      const dhome = Math.hypot(w.x - w.home.x, w.y - w.home.y)
      if (dhome > 90) {
        w.vx += (w.home.x - w.x) * 0.3 * dt
        w.vy += (w.home.y - w.y) * 0.3 * dt
      }
      const speed = 14
      const nx = w.x + w.vx * dt * 0.5 * speed / 10
      const ny = w.y + w.vy * dt * 0.5 * speed / 10
      if (this.canWalkWild(nx, w.y)) w.x = nx
      if (this.canWalkWild(w.x, ny)) w.y = ny
      if (now - w.spawnedAt > 1000 * 60 * 8) w.expired = true
    }
    this.wilds = this.wilds.filter(w => {
      if (!w.expired) return true
      return false
    })
  }

  canWalkWild(x, y) {
    const hw = 4, hh = 3
    for (const [ox, oy] of [[-hw, -hh], [hw, -hh], [-hw, hh], [hw, hh]]) {
      if (this.isSolidTile(Math.floor((x + ox) / TILE), Math.floor((y + oy) / TILE))) return false
    }
    if (Math.hypot(x - this.player.x, y - this.player.y) < 26) return false
    return true
  }

  updateSpawns(dt) {
    for (const b of BIOME_LIST) {
      const count = this.wilds.filter(w => w.biome === b.id).length
      if (count < 3) {
        this.spawnTimers[b.id] = (this.spawnTimers[b.id] || 0) + dt
        if (this.spawnTimers[b.id] > 4) {
          this.spawnTimers[b.id] = 0
          this.spawnWild(b.id)
        }
      }
    }
  }

  updateResources() {
    const now = performance.now()
    for (const r of this.resources) {
      if (!r.available && now >= r.respawnAt) r.available = true
    }
  }

  closestWild(radius) {
    let best = null, bestD = radius
    for (const w of this.wilds) {
      const d = dist(w.x, w.y, this.player.x, this.player.y)
      if (d < bestD) { bestD = d; best = w }
    }
    return best
  }

  nearestInteraction(radius = 34) {
    const p = this.player
    const options = []
    for (const n of this.npcs) {
      const d = dist(n.x, n.y, p.x, p.y)
      if (d < radius) options.push({ kind: 'npc', entity: n, d })
    }
    for (const r of this.resources) {
      if (!r.available) continue
      const d = dist(r.x, r.y, p.x, p.y)
      if (d < radius) options.push({ kind: 'resource', entity: r, d })
    }
    for (const b of this.bosses) {
      const d = dist(b.x, b.y, p.x, p.y)
      if (d < radius + 12) options.push({ kind: 'boss', entity: b, d })
    }
    for (const m of this.mythics) {
      const d = dist(m.x, m.y, p.x, p.y)
      if (d < radius + 10) options.push({ kind: 'mythic', entity: m, d })
    }
    const wild = this.closestWild(radius)
    if (wild) options.push({ kind: 'wild', entity: wild, d: dist(wild.x, wild.y, p.x, p.y) })
    options.sort((a, b) => a.d - b.d)
    return options[0] || null
  }

  removeWild(wild, { defeated = true } = {}) {
    this.wilds = this.wilds.filter(w => w.id !== wild.id)
    this.encounterCooldown = 2
    const b = BIOMES[wild.biome]
    setTimeout(() => {
      if (this.wilds.filter(w => w.biome === wild.biome).length < 3) this.spawnWild(wild.biome)
    }, 3500)
  }

  removeBoss(boss, captured = false) {
    this.bosses = this.bosses.filter(b => b.id !== boss.id)
    this.state.flags.bosses[boss.biome] = captured ? 'captured' : 'defeated'
    if (!this.state.flags.mythic[boss.biome]) this.spawnMythics()
  }

  removeMythic(mythic, captured = false) {
    this.mythics = this.mythics.filter(m => m.id !== mythic.id)
    this.state.flags.mythic[mythic.biome] = captured ? 'captured' : 'defeated'
  }

  getBossForBiome(biome) {
    return this.bosses.find(b => b.biome === biome) || null
  }

  gatherResource(resource) {
    if (!resource.available) return null
    const count = 1 + (Math.random() < 0.25 ? 1 : 0)
    resource.available = false
    resource.respawnAt = performance.now() + 120000
    recordGather(this.state, resource.item, count)
    return count
  }

  playablePositionsAround(tx, ty, radius = 8) {
    const out = []
    for (let dy = -radius; dy <= radius; dy++) for (let dx = -radius; dx <= radius; dx++) {
      if (!this.isSolidTile(tx + dx, ty + dy)) out.push([tx + dx, ty + dy])
    }
    return out
  }

  getDecosAround(camX, camY, camW, camH) {
    const minX = Math.floor(camX / (TILE * 12)) - 1
    const maxX = Math.floor((camX + camW) / (TILE * 12)) + 1
    const minY = Math.floor(camY / (TILE * 12)) - 1
    const maxY = Math.floor((camY + camH) / (TILE * 12)) + 1
    const out = []
    for (let cy = minY; cy <= maxY; cy++) {
      for (let cx = minX; cx <= maxX; cx++) {
        const chunk = this.decoChunks.get(`${cx},${cy}`)
        if (chunk) out.push(...chunk)
      }
    }
    return out
  }
}

export { T }

// Overworld renderer: camera, baked terrain, y-sorted props/entities, weather,
// day/night lighting and interaction indicators.

import { TILE, MAP_W, MAP_H, WORLD_W, WORLD_H, T } from '../game/world.js'
import { BIOMES, BIOME_ORDER, BIOME_LIST } from '../data/biomes.js'
import { monsterSprite, npcSprite, playerSprite, flipCanvas } from './sprites.js'
import { getMonster } from '../data/monsters.js'
import { clamp, isNight, timeOfDay } from '../core/utils.js'

export class WorldRenderer {
  constructor(canvas, world) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')
    this.world = world
    this.camera = { x: 0, y: 0 }
    this.zoom = 3
    this.time = 0
    this.weather = []
    this.weatherBiome = null
    this.tintCanvas = document.createElement('canvas')
    this.tintCtx = this.tintCanvas.getContext('2d')
    this.resize()
  }

  resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    this.width = window.innerWidth
    this.height = window.innerHeight
    this.canvas.width = Math.floor(this.width * dpr)
    this.canvas.height = Math.floor(this.height * dpr)
    this.canvas.style.width = this.width + 'px'
    this.canvas.style.height = this.height + 'px'
    this.dpr = dpr
    this.zoom = this.width < 640 ? 2 : 3
    this.tintCanvas.width = this.canvas.width
    this.tintCanvas.height = this.canvas.height
    this.viewW = this.canvas.width / this.zoom
    this.viewH = this.canvas.height / this.zoom
    this.weather = []
    this.weatherBiome = null
  }

  centerCamera(px, py) {
    this.camera.x = clamp(px - this.viewW / 2, 0, WORLD_W - this.viewW)
    this.camera.y = clamp(py - this.viewH / 2, 0, WORLD_H - this.viewH)
  }

  updateCamera(px, py, dt) {
    const targetX = clamp(px - this.viewW / 2, 0, WORLD_W - this.viewW)
    const targetY = clamp(py - this.viewH / 2, 0, WORLD_H - this.viewH)
    const lerp = 1 - Math.pow(0.001, dt)
    this.camera.x += (targetX - this.camera.x) * lerp
    this.camera.y += (targetY - this.camera.y) * lerp
  }

  isVisible(x, y, margin = 60) {
    return x > this.camera.x - margin && x < this.camera.x + this.viewW + margin &&
      y > this.camera.y - margin && y < this.camera.y + this.viewH + margin
  }

  render(dt, { player, near, playerMoving, walkTime }) {
    this.time += dt
    const ctx = this.ctx
    const dpr = this.dpr
    const zoom = this.zoom
    const cam = this.camera
    const world = this.world
    const state = world.state

    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.fillStyle = '#101a19'
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height)

    ctx.setTransform(dpr * zoom, 0, 0, dpr * zoom, -cam.x * dpr * zoom, -cam.y * dpr * zoom)
    ctx.imageSmoothingEnabled = false

    // Visible slice of baked ground
    const sx = Math.max(0, Math.floor(cam.x))
    const sy = Math.max(0, Math.floor(cam.y))
    const sw = Math.min(WORLD_W - sx, Math.ceil(this.viewW) + 2)
    const sh = Math.min(WORLD_H - sy, Math.ceil(this.viewH) + 2)
    if (sw > 0 && sh > 0) ctx.drawImage(world.mapCanvas, sx, sy, sw, sh, sx, sy, sw, sh)

    const decos = world.getDecosAround(cam.x, cam.y, this.viewW, this.viewH)
    const renderables = []
    for (const d of decos) {
      const x = d.x * TILE + 8, y = d.y * TILE + 16
      if (!this.isVisible(x, y, 80)) continue
      renderables.push({ y: y, type: 'deco', data: d, baseY: y })
    }
    for (const r of world.resources) {
      if (!r.available || !this.isVisible(r.x, r.y, 40)) continue
      renderables.push({ y: r.y, type: 'resource', data: r, baseY: r.y })
    }
    for (const n of world.npcs) {
      if (!this.isVisible(n.x, n.y, 60)) continue
      renderables.push({ y: n.y, type: 'npc', data: n, baseY: n.y })
    }
    for (const w of world.wilds) {
      if (!this.isVisible(w.x, w.y, 60)) continue
      renderables.push({ y: w.y, type: 'wild', data: w, baseY: w.y })
    }
    for (const b of world.bosses) {
      if (!this.isVisible(b.x, b.y, 90)) continue
      renderables.push({ y: b.y, type: 'boss', data: b, baseY: b.y })
    }
    for (const m of world.mythics) {
      if (!this.isVisible(m.x, m.y, 90)) continue
      renderables.push({ y: m.y, type: 'mythic', data: m, baseY: m.y })
    }
    const moving = playerMoving
    const frame = Math.floor(walkTime * 6) % 2
    renderables.push({ y: player.y, type: 'player', data: { ...player, frame: moving ? frame : 0 }, baseY: player.y })

    renderables.sort((a, b) => a.baseY - b.baseY)

    // Auras behind bosses
    for (const b of [...world.bosses, ...world.mythics]) {
      if (!this.isVisible(b.x, b.y, 90)) continue
      this.drawAura(ctx, b.x, b.y - 16, b.kind === 'mythic' ? '#ffe27a' : '#ff8a4c', b.kind === 'mythic' ? 46 : 34)
    }

    for (const item of renderables) {
      switch (item.type) {
        case 'deco': this.drawDeco(ctx, item.data); break
        case 'resource': this.drawResource(ctx, item.data); break
        case 'npc': this.drawNpc(ctx, item.data, near); break
        case 'wild': this.drawWild(ctx, item.data); break
        case 'boss': this.drawWild(ctx, item.data, true); break
        case 'mythic': this.drawWild(ctx, item.data, true); break
        case 'player': this.drawPlayer(ctx, item.data, near); break
      }
    }

    // ground-level labels for towns
    this.drawTownLabels(ctx)

    // screen-space layers
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    this.drawWeather(ctx, state, dt)
    this.drawLighting(ctx, state, player)
    this.drawPrompts(ctx, near, player)
    this.drawClockHalo(ctx, state)
  }

  // ── entity drawing ────────────────────────────────────────────────────────
  drawShadow(ctx, x, y, w = 12, h = 4) {
    ctx.fillStyle = 'rgba(0,0,0,0.28)'
    ctx.beginPath()
    ctx.ellipse(x, y, w / 2, h / 2, 0, 0, Math.PI * 2)
    ctx.fill()
  }

  drawPlayer(ctx, p, near) {
    this.drawShadow(ctx, p.x, p.y + 1, 14, 5)
    const sprite = playerSprite(p.dir, p.frame)
    ctx.drawImage(sprite, Math.round(p.x - 9), Math.round(p.y - 24 + (p.frame ? -1 : 0)), 18, 26)
    if (near && near.kind === 'npc' && Math.hypot(near.entity.x - p.x, near.entity.y - p.y) < 34) {
      // little exclamation over the player's head
      this.drawBubble(ctx, p.x, p.y - 40, '!')
    }
  }

  drawNpc(ctx, n, near) {
    this.drawShadow(ctx, n.x, n.y + 10, 14, 5)
    const sprite = npcSprite(n.look || n.role, n.dir || 'down', 0)
    ctx.drawImage(sprite, Math.round(n.x - 9), Math.round(n.y - 14), 18, 26)
    // role badge
    ctx.font = 'bold 7px monospace'
    ctx.textAlign = 'center'
    const glyph = n.role === 'healer' ? '✚' : n.role === 'shop' ? '◈' : n.role === 'quest' ? '!' : n.role === 'trainer' ? '⚔' : n.role === 'nursery' ? '◈' : ''
    if (glyph) {
      ctx.fillStyle = 'rgba(10,14,18,0.75)'
      ctx.beginPath(); ctx.roundRect(n.x - 5, n.y - 34, 10, 10, 3); ctx.fill()
      ctx.fillStyle = n.role === 'healer' ? '#8ee08a' : n.role === 'trainer' ? '#ff9a9a' : n.role === 'quest' ? '#ffd36e' : '#e3b96b'
      ctx.fillText(glyph, n.x, n.y - 26)
    }
  }

  drawWild(ctx, w, big = false) {
    const t = this.time * 2 + (w.bob || 0)
    const bob = Math.sin(t) * (big ? 2 : 1.4)
    const scale = big ? 2.05 : 1.15
    const sprite = monsterSprite(w.speciesId)
    const flip = w.dir === 'left'
    const drawSprite = flip ? this.flipped(sprite) : sprite
    const wSize = 40 * scale, hSize = 40 * scale
    const baseX = w.x - wSize / 2
    const baseY = w.y + 8 - hSize + bob
    this.drawShadow(ctx, w.x, w.y + 7, big ? 34 : 20, big ? 9 : 6)
    if (big) {
      ctx.save()
      const pulse = 0.5 + Math.sin(this.time * 3 + (w.bob || 0)) * 0.2
      ctx.globalAlpha = 0.35
      ctx.fillStyle = w.kind === 'mythic' ? '#ffe27a' : '#ff8a4c'
      ctx.beginPath(); ctx.ellipse(w.x, w.y + 4, 26 + pulse * 6, 10 + pulse * 2, 0, 0, Math.PI * 2); ctx.fill()
      ctx.restore()
    }
    ctx.drawImage(drawSprite, Math.round(baseX), Math.round(baseY), wSize, hSize)
    if (big) {
      const sp = getMonster(w.speciesId)
      ctx.textAlign = 'center'
      ctx.font = 'bold 6px monospace'
      ctx.fillStyle = 'rgba(8,10,16,0.75)'
      const width = Math.max(46, sp.name.length * 5 + 14)
      ctx.beginPath(); ctx.roundRect(w.x - width / 2, w.y - 62, width, 10, 3); ctx.fill()
      ctx.fillStyle = w.kind === 'mythic' ? '#ffe27a' : '#ffc2a1'
      ctx.fillText(`${sp.name} Lv.${w.monster.level}`, w.x, w.y - 54)
    }
    if (w.kind === 'wild' && this.nearWild === w.id) this.drawBubble(ctx, w.x, w.y - 34, '!')
  }

  flipped(canvas) {
    if (!canvas._flipped) canvas._flipped = flipCanvas(canvas)
    return canvas._flipped
  }

  drawBubble(ctx, x, y, glyph) {
    const bob = Math.sin(this.time * 4) * 2
    ctx.fillStyle = 'rgba(14,18,26,0.85)'
    ctx.beginPath(); ctx.roundRect(x - 7, y - 8 + bob, 14, 13, 4); ctx.fill()
    ctx.strokeStyle = 'rgba(255,226,122,0.8)'; ctx.lineWidth = 1; ctx.stroke()
    ctx.fillStyle = '#ffe27a'
    ctx.font = 'bold 10px monospace'
    ctx.textAlign = 'center'
    ctx.fillText(glyph, x, y + 2 + bob)
  }

  drawResource(ctx, r) {
    const bob = Math.sin(this.time * 2.4 + r.tx) * 1.2
    const glow = r.item === 'stardust' || r.item === 'crystal_shard'
    ctx.save()
    ctx.translate(r.x, r.y - 4 + bob)
    if (glow) {
      ctx.globalAlpha = 0.25
      ctx.fillStyle = '#ffe9a8'
      ctx.beginPath(); ctx.arc(0, 0, 9, 0, Math.PI * 2); ctx.fill()
      ctx.globalAlpha = 1
    }
    // small plant / crystal node
    ctx.fillStyle = 'rgba(0,0,0,0.25)'
    ctx.beginPath(); ctx.ellipse(0, 6, 7, 3, 0, 0, Math.PI * 2); ctx.fill()
    const colors = {
      herb: ['#3f7a48', '#8fe07a'], spring_water: ['#3f86a8', '#b8ecff'], dusk_flower: ['#4a2a68', '#d8b8ff'],
      ember_shard: ['#6b2e22', '#ffb066'], ice_shard: ['#28617f', '#c9f8ff'], crystal_shard: ['#5a4a8a', '#e0c8ff'],
      sun_bloom: ['#7a5c1a', '#ffe27a'], spore_cap: ['#4a2a68', '#b48ae0'], relic_fragment: ['#5e604e', '#e3d6b8'],
      iron_ore: ['#4e5964', '#b8c4d0'], scrap_metal: ['#4e5964', '#c8d0d8'], stardust: ['#7a6418', '#fff3a8'],
      crystal: ['#5a4a8a', '#e0c8ff'],
    }
    const [dark, light] = colors[r.item] || ['#3f7a48', '#8fe07a']
    ctx.strokeStyle = dark; ctx.fillStyle = light; ctx.lineWidth = 2
    if (r.item.includes('crystal') || r.item === 'ice_shard' || r.item === 'ember_shard' || r.item === 'stardust') {
      ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(5, -2); ctx.lineTo(2, 5); ctx.lineTo(-3, 5); ctx.lineTo(-5, -2); ctx.closePath()
      ctx.fill(); ctx.stroke()
      ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fillRect(-1, -7, 1, 4)
    } else if (r.item === 'herb' || r.item === 'dusk_flower' || r.item === 'sun_bloom' || r.item === 'spore_cap') {
      ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI * 2); ctx.fill(); ctx.stroke()
      ctx.fillStyle = dark; ctx.fillRect(-1, 2, 2, 6)
      if (r.item === 'spore_cap') { ctx.fillStyle = light; ctx.fillRect(-4, -1, 8, 2) }
    } else {
      ctx.fillRect(-5, -4, 10, 9)
      ctx.strokeStyle = dark; ctx.strokeRect(-5, -4, 10, 9)
      ctx.fillStyle = '#e8d8b0'; ctx.fillRect(-2, -1, 2, 2)
    }
    ctx.restore()
    if (this.time * 2 % 2 > 1.2) {
      ctx.fillStyle = 'rgba(255,240,180,0.8)'
      ctx.fillRect(r.x + 4, r.y - 16, 2, 2)
    }
  }

  drawAura(ctx, x, y, color, radius) {
    const grad = ctx.createRadialGradient(x, y, 0, x, y, radius)
    grad.addColorStop(0, color + '66')
    grad.addColorStop(0.6, color + '22')
    grad.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.fillStyle = grad
    ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.fill()
    ctx.restore()
  }

  // ── decorations ───────────────────────────────────────────────────────────
  drawDeco(ctx, d) {
    const x = d.x * TILE + 8
    const y = d.y * TILE + 16
    const pal = BIOMES[d.biome]?.palette || BIOMES.forest.palette
    const v = d.variant || 0
    const r = (dx, dy, w, h, color) => { ctx.fillStyle = color; ctx.fillRect(x + dx, y + dy, w, h) }
    const circle = (cx, cy, rad, color) => {
      ctx.fillStyle = color; ctx.beginPath(); ctx.arc(x + cx, y + cy, rad, 0, Math.PI * 2); ctx.fill()
    }
    const tri = (pts, color) => {
      ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(x + pts[0], y + pts[1])
      for (let i = 2; i < pts.length; i += 2) ctx.lineTo(x + pts[i], y + pts[i + 1])
      ctx.closePath(); ctx.fill()
    }
    const shadow = (w = 18) => { ctx.fillStyle = 'rgba(0,0,0,0.22)'; ctx.beginPath(); ctx.ellipse(x, y + 1, w / 2, 4, 0, 0, Math.PI * 2); ctx.fill() }

    switch (d.type) {
      case 'tree': {
        shadow(22)
        r(-3, -10, 6, 12, '#4a3324')
        r(-2, -10, 2, 12, '#6b4a30')
        circle(0, -24, 13, '#204a2c')
        circle(-5, -28, 9, '#2f6b3d')
        circle(5, -27, 8, '#2f6b3d')
        circle(-2, -32, 8, pal.ground3)
        circle(4, -21, 7, '#3f7a48')
        if (v === 1) { circle(-8, -20, 4, '#8fe07a') }
        if (v === 3) { circle(7, -33, 3, '#ffe27a') }
        break
      }
      case 'deadTree': {
        shadow(16)
        r(-2, -24, 4, 26, '#3a2d2a')
        r(-2, -18, 10, 3, '#3a2d2a')
        r(-9, -22, 7, 2, '#3a2d2a')
        r(-8, -26, 2, 5, '#3a2d2a')
        r(6, -25, 2, 8, '#3a2d2a')
        r(-11, -29, 2, 8, '#3a2d2a')
        circle(-10, -30, 2, pal.accent)
        break
      }
      case 'pine': {
        shadow(18)
        r(-2, -8, 4, 9, '#4a3324')
        tri([0, -38, -11, -16, 11, -16], '#1e4a3a')
        tri([0, -31, -9, -10, 9, -10], '#2b5e48')
        tri([0, -36, -5, -20, 5, -20], '#d8eef5')
        break
      }
      case 'bush': {
        circle(-4, -5, 6, '#2f6b3d'); circle(4, -5, 6, '#3f7a48'); circle(0, -8, 7, '#4b8a52')
        if (v % 2) circle(2, -10, 2, '#ffd36e')
        break
      }
      case 'flowers': {
        for (let i = 0; i < 4; i++) {
          const ox = (i * 5 + v * 3) % 12 - 6
          r(ox, -3, 1, 4, '#3f7a48')
          circle(ox, -4, 1.8, i % 2 ? '#ffd36e' : '#ff9fb8')
        }
        break
      }
      case 'fern': {
        for (let i = 0; i < 3; i++) {
          const a = -2 + i
          ctx.strokeStyle = '#6fce74'; ctx.lineWidth = 1
          ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x + a * 4, y - 8, x + a * 5, y - 12); ctx.stroke()
        }
        break
      }
      case 'stump': {
        shadow(12); r(-5, -6, 10, 7, '#5a3f2a'); circle(0, -6, 5, '#8a6844'); circle(0, -6, 2, '#6b4a30')
        break
      }
      case 'cactus': {
        shadow(12); r(-3, -18, 6, 19, '#3f7a48'); r(-8, -12, 4, 4, '#3f7a48'); r(-8, -6, 4, 8, '#3f7a48')
        r(4, -9, 4, 5, '#3f7a48'); r(4, -4, 4, 7, '#3f7a48')
        r(-2, -16, 1, 14, '#6fce74'); r(-9, -14, 1, 5, '#6fce74')
        if (v % 2) circle(0, -20, 2, '#ffd36e')
        break
      }
      case 'crystal': {
        shadow(16)
        tri([-5, 0, -2, -24, 2, 0], '#8a6ad8'); tri([-2, 0, 3, -30, 7, 0], '#b48ae0'); tri([5, 0, 8, -16, 11, 0], '#d8c0ff')
        tri([0, -2, 2, -20, 5, -2], '#e8d8ff')
        ctx.globalAlpha = 0.3; circle(3, -14, 12, '#c9b3ff'); ctx.globalAlpha = 1
        break
      }
      case 'rock': {
        shadow(16); circle(-4, -5, 7, '#5e604e'); circle(4, -6, 6, '#6e705c'); circle(0, -9, 4, '#8a8c76')
        break
      }
      case 'iceRock': {
        shadow(16); tri([-9, 0, -4, -16, 1, 0], '#6fb8cc'); tri([-3, 0, 3, -22, 8, 0], '#a9ddec'); tri([2, 0, 7, -12, 11, 0], '#d5f4ff')
        r(-3, -12, 2, 3, '#f4ffff')
        break
      }
      case 'obsidian': {
        shadow(14); tri([-8, 0, -4, -18, 0, 0], '#1d1418'); tri([-2, 0, 2, -24, 7, 0], '#2b1d28'); tri([4, 0, 8, -14, 11, 0], '#1d1418')
        r(-1, -16, 1, 6, '#ff8a4c')
        break
      }
      case 'lavaRock': {
        shadow(14); circle(0, -6, 8, '#3b2a26'); circle(-5, -8, 5, '#4b3630'); r(-6, -5, 4, 1, '#ff8a4c'); r(1, -8, 5, 1, '#ffb066')
        break
      }
      case 'vent': {
        shadow(12); circle(0, -1, 6, '#3b2a26'); circle(0, -2, 4, '#ff8a4c')
        ctx.globalAlpha = 0.35; circle(2, -14 + Math.sin(this.time + v) * 2, 5, '#ffd8b0'); ctx.globalAlpha = 1
        break
      }
      case 'forge': {
        shadow(24); r(-10, -16, 20, 16, '#4b3b3a'); r(-8, -18, 16, 3, '#6d5347')
        r(-3, -12, 6, 8, '#ff8a4c'); r(-2, -10, 4, 5, '#ffd36e')
        r(-11, -20, 3, 14, '#3b3030')
        break
      }
      case 'pillar': {
        shadow(18); r(-6, -26, 12, 27, '#8a8570'); r(-7, -28, 14, 4, '#b0aa92'); r(-7, -2, 14, 4, '#6e705c')
        r(-4, -24, 2, 22, '#b8b29a'); if (v % 2) r(-1, -18, 2, 6, '#5e604e')
        break
      }
      case 'rubble': {
        circle(-5, -3, 4, '#8a8570'); circle(3, -2, 3, '#6e705c'); r(-1, -6, 5, 3, '#9a957e')
        break
      }
      case 'urn': {
        shadow(10); ctx.fillStyle = '#a87f5a'; ctx.beginPath(); ctx.ellipse(x, y - 6, 5, 7, 0, 0, Math.PI * 2); ctx.fill()
        r(-3, -14, 6, 2, '#8a5f3a')
        break
      }
      case 'stairs': {
        for (let i = 0; i < 3; i++) r(-8 + i * 2, -3 - i * 5, 16 - i * 4, 4, i % 2 ? '#8a8570' : '#a8a38a')
        break
      }
      case 'gear': {
        shadow(10); circle(0, -5, 7, '#6b7078'); circle(0, -5, 3, '#3d4248')
        for (let a = 0; a < 6; a++) { r(-1 + Math.cos(a) * 8, -6 + Math.sin(a) * 8, 2, 2, '#8a9098') }
        break
      }
      case 'bone': {
        shadow(14); r(-8, -4, 12, 2, '#d8d0b8'); r(-8, -1, 12, 2, '#c8c0a8'); circle(-9, -3, 2, '#e8e0c8'); circle(5, -3, 2, '#e8e0c8')
        break
      }
      case 'spike': {
        shadow(18); tri([-8, 0, 0, -34, 8, 0], '#d8d0b8'); tri([-3, 0, 0, -30, 3, 0], '#f0e8d0'); r(-1, -22, 2, 12, '#b8b098')
        break
      }
      case 'nest': {
        shadow(20); ctx.strokeStyle = '#7a5a3a'; ctx.lineWidth = 2
        ctx.beginPath(); ctx.ellipse(x, y - 3, 10, 5, 0, 0, Math.PI * 2); ctx.stroke()
        circle(0, -5, 4, '#e8e0c8'); circle(3, -6, 3, '#d8d0b8')
        break
      }
      case 'spring': {
        ctx.fillStyle = 'rgba(120,220,230,0.55)'; ctx.beginPath(); ctx.ellipse(x, y - 2, 10, 5, 0, 0, Math.PI * 2); ctx.fill()
        ctx.fillStyle = 'rgba(220,255,255,0.6)'; ctx.fillRect(x - 5, y - 3, 4, 1)
        break
      }
      case 'banner': {
        shadow(8); r(-1, -30, 2, 31, '#4a3324'); r(1, -29, 12, 12, '#8a2f3a')
        r(3, -26, 6, 4, '#ffd36e'); r(1, -18, 12, 2, '#6b222a')
        break
      }
      case 'mushroom': {
        shadow(8); r(-1, -7, 3, 7, '#d8d0b8'); circle(1, -8, 6, '#5b3a7e'); circle(0, -9, 4, '#b48ae0')
        if (v % 2) circle(-2, -10, 1, '#ffe27a')
        break
      }
      case 'wisp': {
        ctx.globalAlpha = 0.3; circle(0, -12 + Math.sin(this.time * 2 + v) * 2, 8, '#b48ae0'); ctx.globalAlpha = 1
        circle(0, -12 + Math.sin(this.time * 2 + v) * 2, 3, '#e8d8ff')
        break
      }
      case 'skull': {
        circle(0, -4, 5, '#d8d0b8'); r(-3, -4, 2, 3, '#3b3030'); r(1, -4, 2, 3, '#3b3030'); r(-4, -1, 8, 2, '#b8b098')
        break
      }
      case 'snowdrift': {
        ellipse(x, y - 2, 10, 4, '#e8f4fa')
        break
      }
      case 'ashpile': {
        circle(0, -2, 7, '#3b3130'); circle(-3, -4, 4, '#4b3b3a'); if (v % 2) r(1, -5, 3, 1, '#ff8a4c')
        break
      }
      case 'reed': {
        for (let i = 0; i < 4; i++) {
          const ox = -4 + i * 3
          r(ox, -14, 1, 15, '#5a7a4a')
          r(ox - 1, -16, 3, 2, '#8a9a62')
        }
        break
      }
      case 'starflower': {
        for (let i = 0; i < 3; i++) {
          const ox = [-4, 2, 6][i], oy = [-8, -12, -6][i]
          r(ox, oy, 1, 8 - oy / 2, '#4a7a68')
          ctx.fillStyle = '#ffe27a'; circle(ox, oy, 2.5, '#ffe27a'); circle(ox, oy, 1, '#fff8cc')
        }
        break
      }
      case 'cloudstone': {
        circle(-4, -7, 7, '#dce8f0'); circle(5, -8, 6, '#eef6fa'); circle(0, -12, 5, '#ffffff')
        break
      }
      case 'obelisk': {
        shadow(16); r(-5, -35, 10, 36, '#3d3858'); r(-3, -33, 2, 30, '#5a5278')
        r(-2, -27, 4, 2, '#ffe27a'); r(-2, -21, 4, 2, '#ffe27a'); r(-2, -15, 4, 2, '#ffe27a')
        break
      }
      case 'lantern': {
        shadow(8); r(-1, -20, 2, 21, '#4a3324'); r(-4, -27, 8, 8, '#3d3030'); r(-3, -25, 6, 5, '#ffe27a')
        ctx.globalAlpha = 0.25; circle(0, -22, 11, '#ffe27a'); ctx.globalAlpha = 1
        break
      }
      case 'house': {
        this.drawHouse(ctx, x, y, pal, d)
        break
      }
      default: {
        circle(0, -4, 5, '#5e604e')
      }
    }
  }

  drawHouse(ctx, x, y, pal, d) {
    const v = d.variant || 0
    const roofColors = ['#7a3f3a', '#4a5a7a', '#5a4a3a', '#3a5a4a']
    const roof = roofColors[v % roofColors.length]
    ctx.fillStyle = 'rgba(0,0,0,0.25)'
    ctx.beginPath(); ctx.ellipse(x, y + 1, 26, 5, 0, 0, Math.PI * 2); ctx.fill()
    // walls
    ctx.fillStyle = '#c8b48a'; ctx.fillRect(x - 18, y - 26, 36, 27)
    ctx.fillStyle = '#a89470'; ctx.fillRect(x - 18, y - 8, 36, 9)
    // frame
    ctx.strokeStyle = '#5a4630'; ctx.lineWidth = 2; ctx.strokeRect(x - 18, y - 26, 36, 27)
    // roof
    ctx.fillStyle = roof
    ctx.beginPath(); ctx.moveTo(x - 24, y - 25); ctx.lineTo(x, y - 44); ctx.lineTo(x + 24, y - 25); ctx.closePath(); ctx.fill()
    ctx.fillStyle = 'rgba(255,255,255,0.13)'
    ctx.beginPath(); ctx.moveTo(x - 24, y - 25); ctx.lineTo(x, y - 44); ctx.lineTo(x - 2, y - 25); ctx.closePath(); ctx.fill()
    ctx.strokeStyle = '#3a2a20'; ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(x - 24, y - 25); ctx.lineTo(x, y - 44); ctx.lineTo(x + 24, y - 25); ctx.stroke()
    // door and windows
    ctx.fillStyle = '#5a3a26'; ctx.fillRect(x - 5, y - 16, 10, 17)
    ctx.fillStyle = '#ffd36e'; ctx.fillRect(x - 3, y - 12, 2, 2)
    ctx.fillStyle = '#ffe9a8'; ctx.fillRect(x - 14, y - 20, 5, 5); ctx.fillRect(x + 9, y - 20, 5, 5)
    ctx.strokeStyle = '#5a4630'; ctx.strokeRect(x - 14, y - 20, 5, 5); ctx.strokeRect(x + 9, y - 20, 5, 5)
    // chimney + sign
    ctx.fillStyle = '#6b5a4a'; ctx.fillRect(x + 10, y - 42, 6, 10)
    ctx.fillStyle = pal.accent; ctx.fillRect(x - 3, y - 31, 6, 3)
  }

  // ── screen space ──────────────────────────────────────────────────────────
  worldToScreen(x, y) {
    return { x: (x - this.camera.x) * this.zoom * this.dpr, y: (y - this.camera.y) * this.zoom * this.dpr }
  }

  drawTownLabels(ctx) {
    const z = this.zoom * this.dpr
    for (const b of BIOME_LIST) {
      const t = this.world.towns[b.id]
      const x = (t.x * TILE + 8) * z - this.camera.x * z
      const y = (t.y * TILE - 6) * z - this.camera.y * z
      if (x < 0 || x > this.canvas.width || y < 0 || y > this.canvas.height) continue
      if (Math.hypot(this.world.player.x - (t.x * TILE), this.world.player.y - (t.y * TILE)) > 220 && b.id !== this.world.currentBiome) continue
      ctx.font = `${Math.max(9, 3.2 * z)}px ui-monospace, monospace`
      ctx.textAlign = 'center'
      const label = t.name
      const w = ctx.measureText(label).width + 16 * (z / 3)
      const h = 7 * z
      ctx.fillStyle = 'rgba(12,18,22,0.7)'
      ctx.beginPath(); ctx.roundRect(x - w / 2, y - h, w, h, 3 * (z / 3)); ctx.fill()
      ctx.fillStyle = '#f5e7c8'
      ctx.fillText(label, x, y - h * 0.28)
    }
  }

  weatherForBiome(biome) {
    const count = biome === 'frozen' ? 80 : 55
    const map = {
      forest: { color: '#8fe07a', size: 2, speed: 22, drift: 16, kind: 'leaf' },
      swamp: { color: '#c8a5ff', size: 1.6, speed: 10, drift: 8, kind: 'spore' },
      desert: { color: '#f5dfb0', size: 1.3, speed: 34, drift: 28, kind: 'sand' },
      frozen: { color: '#eefaff', size: 2, speed: 26, drift: 10, kind: 'snow' },
      volcano: { color: '#ff9a5c', size: 1.6, speed: 20, drift: 12, kind: 'ember' },
      ruins: { color: '#d8cbb6', size: 1.2, speed: 12, drift: 6, kind: 'dust' },
      dragon: { color: '#ffb0a8', size: 1.5, speed: 16, drift: 12, kind: 'ember' },
      celestial: { color: '#fff3a8', size: 1.8, speed: 8, drift: 6, kind: 'star' },
    }
    const conf = map[biome] || map.forest
    return Array.from({ length: count }, () => ({
      x: Math.random() * this.width, y: Math.random() * this.height,
      vx: (Math.random() - 0.5) * conf.drift, vy: conf.speed * (0.6 + Math.random() * 0.8),
      size: conf.size * (0.6 + Math.random() * 0.9), phase: Math.random() * 10,
      color: conf.color, kind: conf.kind,
    }))
  }

  drawWeather(ctx, state, dt) {
    const biome = this.world.currentBiome
    if (this.weatherBiome !== biome) { this.weatherBiome = biome; this.weather = this.weatherForBiome(biome) }
    const z = this.dpr
    const night = isNight(state.time.minutes)
    for (const p of this.weather) {
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.phase += dt
      if (p.y > this.height + 10) { p.y = -10; p.x = Math.random() * this.width }
      if (p.x < -10) p.x = this.width + 10
      if (p.x > this.width + 10) p.x = -10
      ctx.globalAlpha = night ? 0.55 : 0.75
      ctx.fillStyle = p.color
      if (p.kind === 'star') {
        ctx.globalAlpha = 0.4 + Math.abs(Math.sin(p.phase * 2)) * 0.5
        ctx.fillRect(p.x * z, p.y * z, p.size * z, p.size * z)
      } else if (p.kind === 'leaf') {
        ctx.save(); ctx.translate(p.x * z, p.y * z); ctx.rotate(Math.sin(p.phase) * 0.8)
        ctx.fillRect(0, 0, p.size * 1.6 * z, p.size * z); ctx.restore()
      } else if (p.kind === 'sand') {
        ctx.fillRect(p.x * z, p.y * z, p.size * 2.6 * z, p.size * 0.7 * z)
      } else if (p.kind === 'ember') {
        ctx.globalAlpha = 0.3 + Math.abs(Math.sin(p.phase * 3)) * 0.6
        ctx.fillRect(p.x * z, p.y * z, p.size * z, p.size * z)
      } else {
        ctx.fillRect(p.x * z, p.y * z, p.size * z, p.size * z)
      }
    }
    ctx.globalAlpha = 1
  }

  drawLighting(ctx, state, player) {
    const mins = state.time.minutes
    const hour = (mins / 60) % 24
    let alpha = 0
    let color = 'rgba(8,12,32,'
    if (hour >= 20 || hour < 5) { alpha = 0.52; color = 'rgba(8,12,32,' }
    else if (hour >= 18) { alpha = 0.26 * ((hour - 18) / 2); color = 'rgba(50,25,40,' }
    else if (hour < 7) { alpha = 0.2 * (1 - (hour - 5) / 2); color = 'rgba(20,20,50,' }
    if (alpha <= 0.01) return
    const c = this.tintCtx
    const dpr = this.dpr
    c.setTransform(1, 0, 0, 1, 0, 0)
    c.clearRect(0, 0, this.tintCanvas.width, this.tintCanvas.height)
    c.fillStyle = color + alpha + ')'
    c.fillRect(0, 0, this.tintCanvas.width, this.tintCanvas.height)
    c.globalCompositeOperation = 'destination-out'
    const punch = (wx, wy, radius) => {
      const s = this.worldToScreen(wx, wy)
      const grd = c.createRadialGradient(s.x, s.y, 0, s.x, s.y, radius * dpr)
      grd.addColorStop(0, 'rgba(0,0,0,0.95)')
      grd.addColorStop(0.55, 'rgba(0,0,0,0.55)')
      grd.addColorStop(1, 'rgba(0,0,0,0)')
      c.fillStyle = grd
      c.beginPath(); c.arc(s.x, s.y, radius * dpr, 0, Math.PI * 2); c.fill()
    }
    punch(player.x, player.y - 8, 105)
    for (const b of this.world.bosses) punch(b.x, b.y - 10, 70)
    for (const m of this.world.mythics) punch(m.x, m.y - 10, 80)
    for (const t of Object.values(this.world.towns)) {
      if (Math.hypot(t.x * TILE - player.x, t.y * TILE - player.y) < 500) punch(t.x * TILE, t.y * TILE, 110)
    }
    c.globalCompositeOperation = 'source-over'
    ctx.drawImage(this.tintCanvas, 0, 0)
  }

  drawPrompts(ctx, near, player) {
    if (!near) return
    const z = this.zoom * this.dpr
    const e = near.entity
    const sx = e.x * z - this.camera.x * z
    const sy = e.y * z - this.camera.y * z
    if (near.kind === 'wild') return
    const glyph = near.kind === 'npc' ? (e.role === 'trainer' ? '⚔' : '…') : near.kind === 'resource' ? '✧' : (near.kind === 'boss' || near.kind === 'mythic') ? '⚔' : '?'
    const bob = Math.sin(this.time * 4) * 3
    const py = sy - (near.kind === 'boss' || near.kind === 'mythic' ? 120 * (z / 3) : 54 * (z / 3)) + bob
    ctx.fillStyle = 'rgba(12,18,24,0.9)'
    ctx.beginPath(); ctx.roundRect(sx - 11, py - 11, 22, 22, 6); ctx.fill()
    ctx.strokeStyle = 'rgba(255,226,122,0.85)'; ctx.lineWidth = 1.5; ctx.stroke()
    ctx.fillStyle = '#ffe27a'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
    ctx.font = `${12 * (z / 3)}px monospace`
    ctx.fillText(glyph, sx, py + 1)
    ctx.textBaseline = 'alphabetic'
  }

  drawClockHalo(ctx, state) {
    // minimal day/night indicator in the top-centre of the canvas (HUD also shows it)
    const hour = (state.time.minutes / 60) % 24
    if (hour >= 19 || hour < 6) {
      const grad = ctx.createLinearGradient(0, 0, 0, 90 * this.dpr)
      grad.addColorStop(0, 'rgba(5,8,24,0.35)')
      grad.addColorStop(1, 'rgba(5,8,24,0)')
      ctx.fillStyle = grad
      ctx.fillRect(0, 0, this.canvas.width, 90 * this.dpr)
    }
  }
}

export { TILE, MAP_W, MAP_H, WORLD_W, WORLD_H, T, BIOMES, BIOME_ORDER }

