// Shared UI primitives: modals, toasts, bars, badges, sprite images.

import { el, clamp } from '../core/utils.js'
import { monsterSprite } from '../render/sprites.js'
import { getMonster } from '../data/monsters.js'
import { ELEMENTS, RARITY, STATUS } from '../data/elements.js'
import { getItem } from '../data/items.js'
import { getSkill } from '../data/skills.js'
import { maxHpOf, xpProgress } from '../game/monsters.js'

export { el }

let modalRoot = null
let toastRoot = null
let modalState = { open: false, onClose: null }

export function initUI() {
  modalRoot = document.getElementById('modal-layer')
  toastRoot = document.getElementById('toast-layer')
}

export function isModalOpen() { return modalState.open }

export function openModal({ title = '', subtitle = '', eyebrow = '', icon = '', body, footer = null, size = 'medium', onClose = null, className = '' }) {
  closeModal(true)
  const backdrop = el('div', { class: 'modal-backdrop' })
  const panel = el('div', { class: `screen-panel size-${size} ${className}` })
  const closeBtn = el('button', { class: 'icon-btn close-btn', title: 'Close (Esc)', onclick: () => closeModal() }, '✕')
  const head = el('header', { class: 'screen-head' }, [
    el('div', { class: 'screen-head-text' }, [
      eyebrow ? el('div', { class: 'eyebrow' }, eyebrow) : null,
      el('h2', {}, [icon ? el('span', { class: 'head-icon' }, icon) : null, title]),
      subtitle ? el('p', { class: 'screen-sub' }, subtitle) : null,
    ]),
    closeBtn,
  ])
  const bodyEl = el('div', { class: 'screen-body' }, body ? [body] : [])
  const footEl = footer ? el('footer', { class: 'screen-foot' }, [].concat(footer)) : null
  panel.append(head, bodyEl)
  if (footEl) panel.append(footEl)
  backdrop.append(panel)
  modalRoot.append(backdrop)
  requestAnimationFrame(() => backdrop.classList.add('visible'))
  modalState = { open: true, onClose, backdrop }
  return { backdrop, panel, body: bodyEl, footer: footEl, close: closeModal }
}

export function closeModal(silent = false) {
  if (!modalRoot) return
  const state = modalState
  if (!state.open) return
  state.open = false
  const backdrop = modalRoot.querySelector('.modal-backdrop')
  if (backdrop) {
    backdrop.classList.remove('visible')
    setTimeout(() => backdrop.remove(), 160)
  }
  const cb = state.onClose
  modalState = { open: false, onClose: null }
  if (!silent && cb) cb()
}

export function toast({ title, text = '', icon = '✦', tone = 'default', duration = 3200 }) {
  if (!toastRoot) return
  const item = el('div', { class: `toast tone-${tone}` }, [
    el('div', { class: 'toast-icon' }, icon),
    el('div', { class: 'toast-copy' }, [
      el('strong', {}, title),
      text ? el('span', {}, text) : null,
    ]),
  ])
  toastRoot.append(item)
  requestAnimationFrame(() => item.classList.add('visible'))
  setTimeout(() => {
    item.classList.remove('visible')
    setTimeout(() => item.remove(), 300)
  }, duration)
}

export function spriteImg(source, { className = '', size = 96, flip = false, alt = '' } = {}) {
  const img = el('img', { class: `pixel-sprite ${className}`, alt, draggable: 'false' })
  img.src = typeof source === 'string' ? source : source.toDataURL()
  img.style.width = size + 'px'
  img.style.height = size + 'px'
  if (flip) img.style.transform = 'scaleX(-1)'
  img.loading = 'eager'
  return img
}

export function monsterSpriteImg(speciesId, opts = {}) {
  const img = el('img', { class: `pixel-sprite ${opts.className || ''}`, alt: getMonster(speciesId).name, draggable: 'false' })
  img.src = monsterSprite(speciesId, { egg: opts.egg, hatchRatio: opts.hatchRatio }).toDataURL()
  img.style.width = (opts.size || 96) + 'px'
  img.style.height = (opts.size || 96) + 'px'
  if (opts.flip) img.style.transform = 'scaleX(-1)'
  return img
}

export function elementBadge(element, small = false) {
  const e = ELEMENTS[element] || ELEMENTS.none
  return el('span', { class: `element-badge ${small ? 'small' : ''}`, style: { '--el': e.color, '--el-dark': e.dark } }, [
    el('span', { class: 'el-glyph' }, e.glyph), el('span', {}, e.name),
  ])
}

export function rarityBadge(rarity) {
  const r = RARITY[rarity] || RARITY.common
  return el('span', { class: 'rarity-badge', style: { color: r.color } }, r.name)
}

export function statusBadge(status) {
  if (!status) return null
  const s = STATUS[status]
  return el('span', { class: 'status-badge', style: { '--status': s.color } }, `${s.glyph} ${s.name}`)
}

export function hpBar(current, max, { className = '', showText = true, width } = {}) {
  const pct = clamp(current / Math.max(1, max), 0, 1) * 100
  const tone = pct > 50 ? 'good' : pct > 22 ? 'warn' : 'bad'
  return el('div', { class: `hp-bar ${className} ${tone}`, style: width ? { width: width + 'px' } : {} }, [
    el('div', { class: 'hp-track' }, [el('div', { class: 'hp-fill', style: { width: pct + '%' } })]),
    showText ? el('span', { class: 'hp-text' }, `${Math.max(0, Math.ceil(current))} / ${max}`) : null,
  ])
}

export function xpBar(monster, { showText = true } = {}) {
  const p = xpProgress(monster)
  return el('div', { class: 'xp-bar' }, [
    el('div', { class: 'xp-track' }, [el('div', { class: 'xp-fill', style: { width: p.pct * 100 + '%' } })]),
    showText ? el('span', { class: 'xp-text' }, `${p.current} / ${p.need} XP`) : null,
  ])
}

export function monsterIcon(monster, size = 72) {
  if (monster.isEgg) return monsterSpriteImg(monster.speciesId, { size, egg: true, hatchRatio: 1 - monster.hatchSteps / monster.hatchMax })
  return monsterSpriteImg(monster.speciesId, { size })
}

export function monsterName(monster) {
  return monster.nickname || getMonster(monster.speciesId).name
}

export function hpPercent(monster) {
  return clamp(monster.hp / Math.max(1, maxHpOf(monster)), 0, 1)
}

export function chip(text, tone = '') {
  return el('span', { class: `chip ${tone}` }, text)
}

export function itemIcon(itemId, size = 32) {
  const item = getItem(itemId)
  return el('span', { class: 'item-icon', style: { '--item-color': item.color, fontSize: size * 0.6 + 'px' } }, item.icon)
}

export function skillIcon(skillId) {
  const skill = getSkill(skillId)
  const e = ELEMENTS[skill.element] || ELEMENTS.none
  return el('span', { class: 'skill-dot', style: { background: e.color, color: e.dark } }, e.glyph)
}

export function button(label, onclick, { variant = 'primary', icon = '', disabled = false, className = '', title = '' } = {}) {
  return el('button', {
    class: `btn ${variant} ${className}`, onclick, disabled, title,
  }, [icon ? el('span', { class: 'btn-icon' }, icon) : null, el('span', {}, label)])
}

export function tabs(defs, active, onSelect) {
  const bar = el('div', { class: 'tab-bar' })
  for (const def of defs) {
    const b = el('button', { class: `tab-btn ${def.id === active ? 'active' : ''}`, onclick: () => onSelect(def.id) }, def.label)
    bar.append(b)
  }
  return bar
}

export function confirm({ title, text, yes = 'Confirm', no = 'Cancel', onYes, onNo = null, danger = false }) {
  let root
  const body = el('div', { class: 'confirm-body' }, [
    el('p', { class: 'confirm-text' }, text),
    el('div', { class: 'row gap end' }, [
      button(no, () => { closeModal(); onNo?.() }, { variant: 'ghost' }),
      button(yes, () => { closeModal(); onYes?.() }, { variant: danger ? 'danger' : 'primary' }),
    ]),
  ])
  root = openModal({ title, body, size: 'small', icon: danger ? '⚠' : '✦' })
  return root
}

export function progressRow(label, current, target, { done = false } = {}) {
  const pct = clamp(current / Math.max(1, target), 0, 1) * 100
  return el('div', { class: `objective ${done ? 'done' : ''}` }, [
    el('div', { class: 'objective-label' }, [
      el('span', {}, (done ? '✔ ' : '') + label),
      el('span', { class: 'objective-count' }, `${Math.min(current, target)} / ${target}`),
    ]),
    el('div', { class: 'thin-track' }, [el('div', { class: 'thin-fill', style: { width: pct + '%' } })]),
  ])
}

export function emptyState(icon, title, text) {
  return el('div', { class: 'empty-state' }, [
    el('div', { class: 'empty-icon' }, icon),
    el('strong', {}, title),
    el('p', {}, text),
  ])
}

// In-game HUD: trainer card, navigation, party dock, tracked quest, interaction hint.

import { el } from './common.js'
import { BIOMES } from '../data/biomes.js'
import { getMonster } from '../data/monsters.js'
import { monsterSprite } from '../render/sprites.js'
import { trackedQuestData } from '../game/progress.js'
import { trainerTitle } from '../game/state.js'
import { formatTime, isNight, timeOfDay } from '../core/utils.js'
import { maxHpOf } from '../game/monsters.js'
import { STATUS } from '../data/elements.js'

export class HUD {
  constructor(root, app) {
    this.root = root
    this.app = app
    this.last = {}
    this.build()
  }

  build() {
    this.root.innerHTML = ''
    this.trainer = el('button', { class: 'hud-trainer', onclick: () => this.app.openParty(), title: 'Open party' })
    this.region = el('div', { class: 'hud-region' })
    this.timeEl = el('div', { class: 'hud-time' })
    this.nav = el('nav', { class: 'hud-nav' })
    const makeNav = (label, icon, fn, key, cls = '') => {
      const b = el('button', { class: `nav-btn ${cls}`, onclick: fn, title: `${label} (${key})` }, [
        el('span', { class: 'nav-icon' }, icon),
        el('span', { class: 'nav-label' }, label),
        el('span', { class: 'nav-key' }, key),
      ])
      this.nav.append(b)
      return b
    }
    makeNav('Party', '◉', () => this.app.openParty(), 'P')
    makeNav('Codex', '▤', () => this.app.openDex(), 'C')
    makeNav('Bag', '◈', () => this.app.openBag(), 'B')
    makeNav('Map', '⌖', () => this.app.openMap(), 'M')
    makeNav('Quests', '✎', () => this.app.openQuests(), 'J')
    makeNav('Menu', '☰', () => this.app.openMenu(), 'Esc', 'menu-btn')

    const top = el('div', { class: 'hud-top' }, [
      this.trainer,
      el('div', { class: 'hud-center' }, [this.region, this.timeEl]),
      this.nav,
    ])

    this.dock = el('div', { class: 'party-dock' })
    this.quest = el('button', { class: 'hud-quest', onclick: () => this.app.openQuests() })
    this.hint = el('div', { class: 'hud-hint' })
    this.lead = el('div', { class: 'hud-lead' })

    const bottom = el('div', { class: 'hud-bottom' }, [
      this.quest,
      this.hint,
      this.lead,
    ])
    this.root.append(top, this.dock, bottom)
  }

  update() {
    const app = this.app
    const state = app.state
    if (!state) return
    const world = app.world
    const p = state.player
    const biome = BIOMES[world?.currentBiome] || BIOMES.forest
    const lead = state.party.find(m => !m.isEgg && m.hp > 0) || state.party.find(m => !m.isEgg)
    const night = isNight(state.time.minutes)

    // Trainer card (rebuild only when values change)
    const trainerKey = `${p.trainerLevel}|${p.money}|${p.trainerXp}`
    if (this.last.trainerKey !== trainerKey) {
      this.last.trainerKey = trainerKey
      this.trainer.innerHTML = ''
      const avatar = el('img', { class: 'trainer-avatar pixel-sprite', alt: 'trainer' })
      avatar.src = app.playerAvatarUrl()
      const info = el('div', { class: 'trainer-copy' }, [
        el('div', { class: 'trainer-line' }, [
          el('strong', {}, p.name),
          el('span', { class: 'trainer-lv' }, `Lv.${p.trainerLevel}`),
        ]),
        el('div', { class: 'trainer-title-line' }, trainerTitle(p.trainerLevel)),
        el('div', { class: 'trainer-sub' }, [
          el('span', { class: 'money' }, `◈ ${p.money.toLocaleString()}`),
          el('span', { class: 'badges' }, `${Object.values(state.flags.bosses).filter(Boolean).length} / 8 guardians`),
        ]),
      ])
      this.trainer.append(avatar, info)
    }

    const regionKey = `${biome.id}|${night}`
    if (this.last.regionKey !== regionKey) {
      this.last.regionKey = regionKey
      this.region.innerHTML = ''
      this.region.append(
        el('span', { class: 'region-icon', style: { color: biome.hue } }, biome.icon),
        el('div', { class: 'region-copy' }, [
          el('strong', {}, biome.name),
          el('span', {}, `${timeOfDay(state.time.minutes)}${night ? ' · monsters stir' : ''}`),
        ]),
      )
    }

    const timeKey = `${Math.floor(state.time.minutes)}|${state.time.day}`
    if (this.last.timeKey !== timeKey) {
      this.last.timeKey = timeKey
      this.timeEl.innerHTML = ''
      this.timeEl.append(
        el('span', { class: 'clock-icon' }, night ? '☾' : '☀'),
        el('span', {}, formatTime(state.time.minutes)),
        el('span', { class: 'day-label' }, `Day ${state.time.day}`),
      )
    }

    // Party dock
    const dockKey = state.party.map(m => `${m.uid}:${m.hp}:${m.status}:${m.level}:${m.isEgg}`).join('|')
    if (this.last.dockKey !== dockKey) {
      this.last.dockKey = dockKey
      this.dock.innerHTML = ''
      for (let i = 0; i < 6; i++) {
        const m = state.party[i]
        if (!m) {
          this.dock.append(el('div', { class: 'dock-slot empty' }, [el('span', {}, '+')]))
          continue
        }
        const pct = m.isEgg ? 1 : Math.max(0, m.hp / maxHpOf(m))
        const status = m.status ? STATUS[m.status] : null
        const slot = el('button', {
          class: `dock-slot ${m.hp <= 0 && !m.isEgg ? 'fainted' : ''} ${i === 0 ? 'lead' : ''}`,
          onclick: () => this.app.openParty(),
          title: `${m.nickname} · Lv.${m.level}`,
        }, [
          (() => {
            const img = el('img', { class: 'dock-sprite pixel-sprite', alt: m.nickname })
            img.src = monsterSprite(m.speciesId, { egg: m.isEgg, hatchRatio: m.isEgg ? 1 - m.hatchSteps / m.hatchMax : 0 }).toDataURL()
            return img
          })(),
          el('div', { class: 'dock-hp' }, [el('div', { class: 'dock-hp-fill', style: { width: pct * 100 + '%', background: pct > 0.5 ? '#78d9a4' : pct > 0.22 ? '#ffd36e' : '#ff7a7a' } })]),
          status ? el('span', { class: 'dock-status', style: { color: status.color } }, status.glyph) : null,
          el('span', { class: 'dock-lv' }, m.isEgg ? 'EGG' : 'Lv.' + m.level),
        ])
        this.dock.append(slot)
      }
    }

    // Tracked quest
    const tq = trackedQuestData(state)
    const questKey = tq ? `${tq.quest.id}|${tq.status}|${tq.progress.map(o => o.current).join(',')}` : 'none'
    if (this.last.questKey !== questKey) {
      this.last.questKey = questKey
      this.quest.innerHTML = ''
      if (tq) {
        const next = tq.progress.find(o => !o.done) || tq.progress[0]
        this.quest.append(
          el('div', { class: 'quest-eyebrow' }, [el('span', {}, 'TRACKED QUEST'), tq.status === 'ready' ? el('span', { class: 'quest-ready' }, 'READY') : null]),
          el('strong', {}, tq.quest.name),
          el('div', { class: 'quest-obj' }, next ? `${next.label}: ${Math.min(next.current, next.target)}/${next.target}` : ''),
        )
      } else {
        this.quest.append(el('div', { class: 'quest-eyebrow' }, 'QUEST LOG'), el('strong', {}, 'Speak with quest givers'), el('div', { class: 'quest-obj' }, 'Find the golden “!” in every town.'))
      }
    }

    // Hint
    const near = app.near
    let hintText = 'WASD / Arrows to move · E to interact'
    let hintIcon = '⌁'
    if (app.uiBlocked) hintText = ''
    else if (near) {
      const e = near.entity
      if (near.kind === 'npc') { hintText = `Talk to ${e.name}`; hintIcon = e.role === 'trainer' ? '⚔' : e.role === 'healer' ? '✚' : e.role === 'shop' ? '◈' : '…' }
      else if (near.kind === 'resource') { hintText = `Gather ${e.item.replace(/_/g, ' ')}`; hintIcon = '✧' }
      else if (near.kind === 'boss') { hintText = `Challenge ${e.name}`; hintIcon = '⚔' }
      else if (near.kind === 'mythic') { hintText = `A mythic presence…`; hintIcon = '✧' }
      else if (near.kind === 'wild') { hintText = `Wild ${getMonster(e.speciesId).name} Lv.${e.monster.level}`; hintIcon = '◉' }
    } else if (night) { hintText = 'Night falls. Nocturnal monsters are waking.'; hintIcon = '☾' }
    const hintKey = hintText + hintIcon
    if (this.last.hintKey !== hintKey) {
      this.last.hintKey = hintKey
      this.hint.innerHTML = ''
      this.hint.append(el('span', { class: 'hint-icon' }, hintIcon), el('span', {}, hintText))
      this.hint.classList.toggle('hidden', !hintText)
      app.setInteractLabel(near)
    }

    // Lead monster mini card
    const leadKey = lead ? `${lead.uid}:${lead.hp}:${lead.status}` : 'none'
    if (this.last.leadKey !== leadKey) {
      this.last.leadKey = leadKey
      this.lead.innerHTML = ''
      if (lead) {
        const img = el('img', { class: 'lead-sprite pixel-sprite' })
        img.src = monsterSprite(lead.speciesId).toDataURL()
        const pct = lead.hp / maxHpOf(lead)
        this.lead.append(
          img,
          el('div', { class: 'lead-copy' }, [
            el('strong', {}, lead.nickname),
            el('span', {}, `Lv.${lead.level} · ${getMonster(lead.speciesId).name}`),
            el('div', { class: 'lead-hp' }, [el('div', { style: { width: pct * 100 + '%', background: pct > 0.5 ? '#78d9a4' : pct > 0.22 ? '#ffd36e' : '#ff7a7a' } })]),
          ]),
          lead.status ? el('span', { class: 'lead-status', style: { color: STATUS[lead.status].color } }, STATUS[lead.status].glyph) : null,
        )
      }
    }
  }
}

