205: function migrate(data) {
206:   const base = defaultState()
207:   const merged = deepMerge(base, data)
208:   merged.version = SAVE_VERSION
209:   merged.settings = { ...base.settings, ...(data.settings || {}) }
210:   merged.stats = { ...base.stats, ...(data.stats || {}) }
211:   merged.flags = { ...base.flags, ...(data.flags || {}) }
212:   merged.flags.visited = { ...base.flags.visited, ...(data.flags?.visited || {}) }
213:   merged.quests = data.quests || {}
214:   merged.party = data.party || []
215:   merged.storage = data.storage || []
216:   return merged
217: }
218: 
219: function deepMerge(base, extra) {
220:   if (Array.isArray(base)) return Array.isArray(extra) ? extra : base
221:   if (typeof base === 'object' && base !== null) {
222:     const out = { ...base }
223:     if (extra && typeof extra === 'object') {
224:       for (const k of Object.keys(extra)) out[k] = deepMerge(base[k], extra[k])
225:     }
226:     return out
227:   }
228:   return extra !== undefined ? extra : base
229: }
230: 
231: export function saveSummary() {
232:   const state = loadGame()
233:   if (!state) return null
234:   return {
235:     name: state.player?.name || 'Wren',
236:     level: state.player?.trainerLevel || 1,
237:     party: state.party?.length || 0,
238:     dex: Object.keys(state.pokedex?.caught || {}).length,
239:     savedAt: state.savedAt,
240:     playTime: state.stats?.playTime || 0,
241:   }
242: }

