/* ==========================================================================
   AETHERIA: WILDBOUND — game styling
   Hand-built pixel-fantasy UI. No external fonts or frameworks.
   ========================================================================== */

:root {
  --bg: #0a1011;
  --bg2: #0e1617;
  --panel: #121b1c;
  --panel2: #172324;
  --panel3: #1d2b2c;
  --ink: #ece5d3;
  --ink-soft: #c8c4b2;
  --muted: #8e978b;
  --line: rgba(238, 230, 207, 0.12);
  --line-strong: rgba(238, 230, 207, 0.22);
  --gold: #ffe27a;
  --gold-deep: #d8a94c;
  --green: #7ed957;
  --green-deep: #2f6b3d;
  --red: #ff7a7a;
  --red-deep: #8e2f22;
  --blue: #7fd8ef;
  --purple: #b48ae0;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.5);
  --radius: 16px;
  --radius-sm: 10px;
  --font: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.45; }
h1, h2, h3, h4, p { margin: 0; }
p { line-height: 1.55; }
a { color: var(--gold); }
::selection { background: rgba(255, 226, 122, 0.3); }

/* scrollbars */
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-track { background: rgba(0,0,0,0.18); }
*::-webkit-scrollbar-thumb { background: rgba(238,230,207,0.18); border-radius: 99px; border: 2px solid transparent; background-clip: padding-box; }
*::-webkit-scrollbar-thumb:hover { background: rgba(238,230,207,0.3); background-clip: padding-box; }

.hidden { display: none !important; }
.muted { color: var(--muted); }
.pixel-sprite { image-rendering: pixelated; image-rendering: crisp-edges; object-fit: contain; }
.silhouette { filter: brightness(0) opacity(0.55); }

/* utility rows */
.row { display: flex; align-items: center; }
.row.gap { gap: 10px; }
.row.end { justify-content: flex-end; }
.row.between { justify-content: space-between; }
.wrap { flex-wrap: wrap; }
.eyebrow {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 7px;
}
.small-note { font-size: 12px; color: var(--muted); line-height: 1.45; }
.panel-soft {
  background: linear-gradient(172deg, rgba(30, 44, 45, 0.85), rgba(18, 27, 28, 0.9));
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 16px;
}
.panel-soft h3 { font-size: 16px; margin-bottom: 6px; letter-spacing: 0.01em; }
.panel-soft p { font-size: 13px; color: var(--ink-soft); }

/* ==========================================================================
   Shared controls
   ========================================================================== */
.btn {
  --btn-bg: linear-gradient(180deg, #2c8a69, #1f6a51);
  --btn-line: rgba(180, 255, 216, 0.28);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 9px 18px;
  border-radius: 10px;
  border: 1px solid var(--btn-line);
  background: var(--btn-bg);
  color: #f7fff9;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.025em;
  box-shadow: 0 4px 0 rgba(0,0,0,0.24), inset 0 1px 0 rgba(255,255,255,0.18);
  transition: transform 0.12s ease, filter 0.12s ease, box-shadow 0.12s ease;
  white-space: nowrap;
}
.btn:hover:not(:disabled) { filter: brightness(1.12); transform: translateY(-1px); }
.btn:active:not(:disabled) { transform: translateY(1px); box-shadow: 0 1px 0 rgba(0,0,0,0.3); }
.btn .btn-icon { font-size: 15px; line-height: 1; }
.btn.primary { --btn-bg: linear-gradient(180deg, #c79f48, #9d742a); --btn-line: rgba(255, 234, 158, 0.35); color: #21180a; text-shadow: 0 1px 0 rgba(255,255,255,0.2); }
.btn.gold { --btn-bg: linear-gradient(180deg, #ffe27a, #d8a94c); --btn-line: rgba(255,245,190,0.5); color: #241a08; }
.btn.ghost {
  --btn-bg: rgba(255,255,255,0.035);
  --btn-line: var(--line-strong);
  color: var(--ink);
  box-shadow: none;
}
.btn.ghost:hover:not(:disabled) { background: rgba(255,255,255,0.09); }
.btn.danger { --btn-bg: linear-gradient(180deg, #a93e3e, #782626); --btn-line: rgba(255,150,150,0.35); }
.btn.small { min-height: 34px; padding: 7px 13px; font-size: 12px; border-radius: 8px; }
.btn.tiny { min-height: 27px; padding: 4px 9px; font-size: 11px; border-radius: 7px; }

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 34px; height: 34px;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.04);
  color: var(--ink-soft);
  transition: 0.12s ease;
}
.icon-btn:hover { background: rgba(255,255,255,0.11); color: var(--ink); }

.text-input, .select-input {
  width: 100%;
  min-height: 42px;
  padding: 9px 12px;
  border-radius: 9px;
  border: 1px solid var(--line-strong);
  background: rgba(5, 10, 11, 0.55);
  color: var(--ink);
  outline: none;
  font-size: 14px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.text-input:focus, .select-input:focus {
  border-color: rgba(255, 226, 122, 0.6);
  box-shadow: 0 0 0 3px rgba(255, 226, 122, 0.11);
}
.text-input::placeholder { color: #66706a; }
.select-input { appearance: none; background-image: linear-gradient(45deg, transparent 50%, #b9c4aa 50%), linear-gradient(135deg, #b9c4aa 50%, transparent 50%); background-position: calc(100% - 16px) 18px, calc(100% - 11px) 18px; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; padding-right: 30px; }
.select-input option { background: #111a1b; color: var(--ink); }

.tab-bar { display: flex; gap: 5px; flex-wrap: wrap; padding: 4px; background: rgba(0,0,0,0.22); border: 1px solid var(--line); border-radius: 11px; margin-bottom: 16px; }
.tab-btn {
  flex: 1 1 auto;
  min-height: 34px;
  padding: 7px 14px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: 0.13s ease;
}
.tab-btn:hover { color: var(--ink); background: rgba(255,255,255,0.04); }
.tab-btn.active { background: linear-gradient(180deg, rgba(255,226,122,0.18), rgba(255,226,122,0.08)); border-color: rgba(255,226,122,0.3); color: var(--gold); }

.chip {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 8px; border-radius: 99px;
  border: 1px solid var(--line-strong);
  background: rgba(255,255,255,0.04);
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.03em;
  color: var(--ink-soft);
}
.chip.warm { color: #ffc98a; border-color: rgba(255,201,138,0.28); background: rgba(255,160,80,0.09); }
.chip.good { color: #9bf0a9; border-color: rgba(126,217,87,0.3); background: rgba(126,217,87,0.08); }
.chip.gold { color: var(--gold); border-color: rgba(255,226,122,0.32); background: rgba(255,226,122,0.08); }
.chip.soft { color: var(--muted); }
.chip.bad { color: #ffa7a7; border-color: rgba(255,122,122,0.3); background: rgba(255,122,122,0.08); }

.element-badge {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 9px 3px 6px;
  border-radius: 7px;
  color: var(--el);
  background: color-mix(in srgb, var(--el) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--el) 35%, transparent);
  font-size: 11px; font-weight: 800; letter-spacing: 0.04em;
}
.element-badge .el-glyph { display: inline-grid; place-items: center; width: 17px; height: 17px; border-radius: 5px; background: var(--el-dark); color: var(--el); font-size: 10px; }
.element-badge.small { font-size: 9.5px; padding: 2px 6px 2px 4px; }
.element-badge.small .el-glyph { width: 14px; height: 14px; font-size: 9px; }

.rarity-badge { font-size: 10px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; }
.status-badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 7px; border-radius: 99px; background: color-mix(in srgb, var(--status) 15%, transparent); color: var(--status); border: 1px solid color-mix(in srgb, var(--status) 40%, transparent); font-size: 10px; font-weight: 800; }

.hp-bar { display: flex; flex-direction: column; gap: 4px; }
.hp-track { position: relative; height: 10px; border-radius: 99px; background: rgba(0,0,0,0.45); border: 1px solid rgba(255,255,255,0.1); overflow: hidden; box-shadow: inset 0 1px 2px rgba(0,0,0,0.5); }
.hp-fill { height: 100%; border-radius: 99px; transition: width 0.4s cubic-bezier(.2,.8,.2,1), background 0.3s; background: linear-gradient(180deg, #93e6b4, #4cbf83); box-shadow: 0 0 10px rgba(126,217,87,0.2); }
.hp-bar.warn .hp-fill { background: linear-gradient(180deg, #ffe39b, #e5b948); }
.hp-bar.bad .hp-fill { background: linear-gradient(180deg, #ffabab, #d95656); }
.hp-text { font-family: var(--mono); font-size: 10px; color: var(--muted); letter-spacing: 0.02em; }
.hp-bar.good .hp-text { color: #9ddcb1; }

.xp-bar { display: flex; flex-direction: column; gap: 4px; }
.xp-track { height: 5px; border-radius: 99px; background: rgba(0,0,0,0.45); overflow: hidden; }
.xp-fill { height: 100%; border-radius: 99px; background: linear-gradient(90deg, #6d9cff, #b48ae0); }
.xp-text { font-family: var(--mono); font-size: 9.5px; color: var(--muted); }

.thin-track { height: 6px; border-radius: 99px; background: rgba(0,0,0,0.4); overflow: hidden; border: 1px solid rgba(255,255,255,0.07); }
.thin-fill { height: 100%; border-radius: 99px; background: linear-gradient(90deg, #8fd06a, #e0c35a); transition: width 0.35s ease; }
.thin-fill.warm { background: linear-gradient(90deg, #ff9f68, #ffd36e); }

.count-pill { font-family: var(--mono); font-size: 11px; color: var(--gold); background: rgba(255,226,122,0.08); border: 1px solid rgba(255,226,122,0.22); border-radius: 99px; padding: 2px 7px; }
.item-icon { display: inline-grid; place-items: center; width: 38px; height: 38px; flex: 0 0 38px; border-radius: 10px; background: color-mix(in srgb, var(--item-color) 13%, rgba(0,0,0,0.2)); border: 1px solid color-mix(in srgb, var(--item-color) 32%, transparent); color: var(--item-color); }
.skill-dot, .move-icon { display: inline-grid; place-items: center; width: 30px; height: 30px; flex: 0 0 30px; border-radius: 8px; font-size: 13px; }

.empty-state { grid-column: 1 / -1; display: grid; place-items: center; gap: 4px; text-align: center; padding: 48px 24px; border: 1px dashed var(--line-strong); border-radius: var(--radius); color: var(--muted); }
.empty-state .empty-icon { font-size: 34px; opacity: 0.65; }
.empty-state strong { color: var(--ink-soft); font-size: 15px; }
.empty-state p { font-size: 13px; max-width: 340px; }

.quick-link {
  display: flex; align-items: center; gap: 9px;
  width: 100%; min-height: 40px; padding: 9px 12px;
  border: 1px solid var(--line); border-radius: 9px;
  background: rgba(255,255,255,0.03); color: var(--ink-soft);
  font-size: 12px; font-weight: 700; text-align: left;
  transition: 0.13s ease;
}
.quick-link:hover { border-color: rgba(255,226,122,0.32); background: rgba(255,226,122,0.06); color: var(--gold); }

/* ==========================================================================
   Title screen
   ========================================================================== */
.title-screen {
  position: fixed;
  inset: 0;
  overflow: hidden auto;
  background:
    radial-gradient(ellipse at 50% -10%, rgba(255, 226, 122, 0.16), transparent 55%),
    radial-gradient(ellipse at 12% 88%, rgba(126, 217, 87, 0.13), transparent 42%),
    radial-gradient(ellipse at 88% 82%, rgba(180, 138, 224, 0.14), transparent 45%),
    linear-gradient(180deg, #0a1214 0%, #0a1011 48%, #080d0e 100%);
}
.title-screen::before {
  content: "";
  position: absolute; inset: 0;
  background-image:
    radial-gradient(1px 1px at 12% 20%, rgba(255,255,255,0.5), transparent 100%),
    radial-gradient(1px 1px at 38% 8%, rgba(255,255,255,0.35), transparent 100%),
    radial-gradient(1.5px 1.5px at 72% 18%, rgba(255,226,122,0.5), transparent 100%),
    radial-gradient(1px 1px at 89% 35%, rgba(255,255,255,0.4), transparent 100%),
    radial-gradient(1px 1px at 22% 62%, rgba(255,255,255,0.3), transparent 100%),
    radial-gradient(1.5px 1.5px at 62% 78%, rgba(180,138,224,0.45), transparent 100%),
    radial-gradient(1px 1px at 82% 68%, rgba(255,255,255,0.35), transparent 100%);
  background-size: 100% 100%;
  animation: star-drift 14s ease-in-out infinite alternate;
}
.title-screen::after {
  content: "";
  position: absolute; left: 50%; bottom: -22%;
  width: 120vw; height: 50vh; transform: translateX(-50%);
  background: radial-gradient(ellipse at center, rgba(94, 190, 150, 0.12), transparent 65%);
  filter: blur(20px);
}
.title-vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 42%, rgba(0,0,0,0.55)); pointer-events: none; }
.title-content {
  position: relative; z-index: 2;
  min-height: 100dvh;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: clamp(28px, 6vw, 90px);
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: clamp(28px, 6vh, 70px) clamp(22px, 5vw, 60px);
}
.title-left { display: flex; flex-direction: column; align-items: flex-start; gap: 18px; }
.title-kicker {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.24em;
  color: var(--gold); text-transform: uppercase;
  padding: 6px 11px; border: 1px solid rgba(255,226,122,0.28); border-radius: 99px;
  background: rgba(255,226,122,0.05);
}
.title-logo { display: flex; flex-direction: column; gap: 2px; }
.title-logo h1 {
  font-size: clamp(54px, 9vw, 112px);
  line-height: 0.86;
  letter-spacing: -0.045em;
  color: #f6eed9;
  text-shadow: 0 2px 0 #6e5b2c, 0 5px 0 #3a2f18, 0 14px 35px rgba(0,0,0,0.65);
  font-weight: 900;
}
.title-logo .title-sub {
  font-family: var(--mono);
  font-size: clamp(14px, 2vw, 22px);
  letter-spacing: 0.44em;
  color: var(--gold);
  text-indent: 0.44em;
  margin-top: 8px;
  text-shadow: 0 0 20px rgba(255,226,122,0.35);
}
.title-tagline { font-size: clamp(14px, 1.5vw, 17px); color: var(--ink-soft); max-width: 480px; line-height: 1.65; }
.title-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 6px; }
.title-actions .btn { min-height: 48px; padding: 12px 22px; font-size: 14px; }
.title-save {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;
  padding: 10px 14px; border: 1px solid var(--line); border-radius: 11px;
  background: rgba(255,255,255,0.025); font-size: 12px; color: var(--muted);
}
.title-save strong { color: var(--ink); }
.title-save .save-dot { display: inline-block; width: 7px; height: 7px; border-radius: 99px; background: var(--green); box-shadow: 0 0 8px var(--green); margin-right: 5px; }

.title-right { position: relative; min-height: 430px; display: grid; place-items: center; }
.title-orbit {
  position: absolute; inset: 8% 4%;
  border: 1px solid rgba(255,226,122,0.13);
  border-radius: 50%;
  transform: rotate(-12deg);
  box-shadow: inset 0 0 80px rgba(255,226,122,0.04);
}
.title-orbit::before, .title-orbit::after {
  content: ""; position: absolute; inset: 9%;
  border: 1px dashed rgba(180,138,224,0.14); border-radius: 50%;
}
.title-orbit::after { inset: 22%; border-style: solid; border-color: rgba(126,217,87,0.12); }
.title-mons { position: relative; z-index: 2; display: flex; align-items: flex-end; gap: clamp(2px, 2vw, 14px); }
.title-mon {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  animation: gentle-float 6s ease-in-out infinite;
  filter: drop-shadow(0 18px 20px rgba(0,0,0,0.45));
}
.title-mon:nth-child(1) { animation-delay: -1s; transform: translateY(18px) scale(0.9); }
.title-mon:nth-child(2) { animation-delay: -3.2s; transform: translateY(-8px) scale(1.1); z-index: 2; }
.title-mon:nth-child(3) { animation-delay: -4.6s; transform: translateY(22px) scale(0.86); }
.title-mon img { width: clamp(105px, 13vw, 175px); height: clamp(105px, 13vw, 175px); }
.title-mon span { font-family: var(--mono); font-size: 10px; letter-spacing: 0.16em; color: var(--muted); text-transform: uppercase; }
.title-plate {
  position: absolute; bottom: 2%; left: 50%; transform: translateX(-50%);
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.2em; color: rgba(238,230,207,0.36);
  text-transform: uppercase; white-space: nowrap;
}
.title-footer {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 3;
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  padding: 14px clamp(22px, 5vw, 60px);
  font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(238,230,207,0.42);
  border-top: 1px solid rgba(255,255,255,0.06);
  background: linear-gradient(180deg, transparent, rgba(6,10,11,0.6));
}

/* new-journey form */
.newgame-form { display: flex; flex-direction: column; gap: 18px; }
.newgame-form > p { font-size: 13.5px; color: var(--ink-soft); }
.field-label { display: block; font-family: var(--mono); font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); margin-bottom: 7px; }
.starter-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.starter-card {
  position: relative;
  display: flex; flex-direction: column; gap: 8px; align-items: center; text-align: center;
  padding: 16px 10px 13px;
  border: 1px solid var(--line-strong); border-radius: 13px;
  background: linear-gradient(180deg, rgba(255,255,255,0.045), rgba(0,0,0,0.18));
  color: var(--ink); transition: 0.15s ease;
}
.starter-card:hover { transform: translateY(-3px); border-color: rgba(255,226,122,0.4); background: rgba(255,226,122,0.06); }
