.region-copy span { font-family: var(--mono); font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(238,230,207,0.66); }
.hud-time { display: flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 9.5px; color: rgba(238,230,207,0.7); background: rgba(8,13,14,0.45); padding: 3px 9px; border-radius: 99px; border: 1px solid rgba(255,255,255,0.08); }
