.lead-ribbon { position: absolute; top: -1px; left: -1px; font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.1em; padding: 2px 5px; border-radius: 8px 0 7px 0; background: var(--gold); color: #241a08; font-weight: 800; }
.party-info { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.party-name-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.party-name-row strong { font-size: 13.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
