.storage-copy { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.storage-meta { font-family: var(--mono); font-size: 8.5px; color: var(--muted); }
.storage-actions { grid-column: 1 / -1; display: flex; justify-content: flex-end; }

/* ==========================================================================
   Monster detail
   ========================================================================== */
.detail-screen { display: grid; grid-template-columns: 290px minmax(0,1fr); gap: 16px; align-items: start; }
.detail-art { position: sticky; top: 0; display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 16px; border: 1px solid var(--line); border-radius: 13px; background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(0,0,0,0.13)); }
