.detail-meta-grid { width: 100%; display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.meta-pair { display: flex; flex-direction: column; gap: 1px; padding: 6px 8px; border-radius: 7px; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.045); }
.meta-pair span { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--muted); }
.meta-pair strong { font-size: 11px; }
.detail-main { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.detail-block { padding: 14px 15px; }
.block-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 9px; }
.block-head h3 { font-size: 14px; }
.stat-list { display: flex; flex-direction: column; gap: 5px; }
.stat-row { display: grid; grid-template-columns: 58px 38px minmax(0,1fr); align-items: center; gap: 8px; }
.stat-name { font-family: var(--mono); font-size: 9px; letter-spacing: 0.06em; color: var(--muted); text-transform: uppercase; }
.stat-value { font-family: var(--mono); font-size: 11.5px; font-weight: 700; }
.stat-value.plus { color: #9ff0a8; }
.stat-value.minus { color: #ff9c9c; }
.stat-track { height: 7px; border-radius: 99px; background: rgba(0,0,0,0.35); overflow: hidden; }
.stat-fill { height: 100%; border-radius: 99px; background: linear-gradient(90deg, #5e9d78, #8fd6a2); }
.stat-fill.stat-atk { background: linear-gradient(90deg, #b35647, #ff9a7a); }
.stat-fill.stat-def { background: linear-gradient(90deg, #7d7252, #d8c48a); }
.stat-fill.stat-spa { background: linear-gradient(90deg, #665aa3, #b9a5f4); }
.stat-fill.stat-spd { background: linear-gradient(90deg, #4b7f8a, #96d8e4); }
.stat-fill.stat-spe { background: linear-gradient(90deg, #a77b3d, #ffd87a); }
.passive-row { display: flex; gap: 9px; align-items: flex-start; }
.passive-icon { width: 30px; height: 30px; flex: 0 0 30px; display: grid; place-items: center; border-radius: 8px; background: rgba(180,138,224,0.12); border: 1px solid rgba(180,138,224,0.3); color: var(--purple); }
.passive-row p { font-size: 12px; color: var(--muted); margin-top: 2px; }
.move-list { display: flex; flex-direction: column; gap: 5px; }
.move-row { display: grid; grid-template-columns: 30px minmax(0,1fr) auto; gap: 9px; align-items: center; padding: 6px; border: 1px solid rgba(255,255,255,0.05); border-radius: 9px; background: rgba(255,255,255,0.02); }
.move-row.equipped { background: rgba(126,217,87,0.045); border-color: rgba(126,217,87,0.16); }
.move-copy { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.move-name-row { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.move-name-row strong { font-size: 12px; }
.move-power, .move-cost { font-family: var(--mono); font-size: 8px; color: var(--muted); }
.move-copy p { font-size: 10.5px; color: var(--muted); line-height: 1.35; }
.learned-details { margin-top: 8px; }
.learned-details summary { font-size: 11px; color: var(--muted); cursor: pointer; padding: 4px 0; }
.learned-details .move-list { margin-top: 5px; opacity: 0.82; }
.evo-option { display: flex; align-items: center; gap: 11px; padding: 8px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.022); margin-top: 6px; }
.evo-option .pixel-sprite { flex: 0 0 auto; }
.evo-copy { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
.evo-copy span { font-size: 10.5px; color: var(--muted); }
.evo-option.item-evo { border-color: rgba(255,226,122,0.18); }
.egg-block { display: flex; flex-direction: column; gap: 8px; align-items: center; text-align: center; padding: 28px 20px; }
.egg-block .egg-emoji { font-size: 48px; color: var(--gold); animation: gentle-float 4s ease-in-out infinite; }
.egg-block p { font-size: 13px; color: var(--ink-soft); max-width: 420px; }
.egg-block .egg-progress { width: 100%; max-width: 340px; }

.rename-form { display: flex; flex-direction: column; gap: 13px; }
.rename-form p { font-size: 13px; color: var(--ink-soft); }

/* item picker */
.item-picker { display: flex; flex-direction: column; gap: 6px; }
.picker-row { display: grid; grid-template-columns: 38px minmax(0,1fr) auto auto; align-items: center; gap: 10px; padding: 8px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.02); }
.picker-copy { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.picker-copy strong { font-size: 12px; }
.picker-copy span { font-size: 10.5px; color: var(--muted); line-height: 1.3; }
.monster-picker-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 8px; }
.monster-pick-card { display: flex; align-items: center; gap: 9px; text-align: left; padding: 8px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.025); color: var(--ink); transition: 0.12s; }
.monster-pick-card:hover { border-color: rgba(255,226,122,0.3); background: rgba(255,226,122,0.06); }
.monster-pick-card .pixel-sprite { width: 48px; height: 48px; }
.monster-pick-card strong { display: block; font-size: 12px; }
.monster-pick-card .small-note { display: block; }

/* ==========================================================================
   Codex
   ========================================================================== */
.dex-filters { display: grid; grid-template-columns: minmax(160px,1fr) repeat(3, minmax(110px, 170px)); gap: 8px; margin-bottom: 12px; }
.dex-filters .search { min-width: 0; }
.dex-progress { display: grid; grid-template-columns: auto minmax(0,1fr) auto; align-items: center; gap: 10px; margin-bottom: 14px; padding: 9px 12px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.02); }
.dex-progress .eyebrow { margin: 0; }
.dex-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(138px, 1fr)); gap: 8px; }
.dex-card { position: relative; display: flex; flex-direction: column; align-items: center; gap: 5px; padding: 10px 8px 9px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,0.02); color: var(--ink); transition: 0.13s ease; text-align: center; }
.dex-card:hover:not(.unknown) { transform: translateY(-2px); border-color: rgba(255,226,122,0.32); background: rgba(255,226,122,0.05); }
.dex-card.unknown { opacity: 0.55; }
.dex-card.caught { border-color: rgba(126,217,87,0.22); background: rgba(126,217,87,0.03); }
.dex-num { position: absolute; top: 5px; left: 7px; font-family: var(--mono); font-size: 7.5px; color: var(--muted); }
.dex-sprite-wrap { position: relative; width: 64px; height: 64px; display: grid; place-items: center; margin-top: 6px; }
.dex-sprite-wrap .pixel-sprite { width: 64px; height: 64px; }
.dex-check { position: absolute; right: -3px; bottom: -1px; width: 16px; height: 16px; border-radius: 99px; display: grid; place-items: center; background: #4cbf83; color: #062012; font-size: 9px; border: 2px solid #162122; }
.dex-name { font-size: 11.5px; font-weight: 700; }
.dex-tags { display: flex; gap: 4px; justify-content: center; flex-wrap: wrap; min-height: 18px; }

.dex-entry { display: grid; grid-template-columns: 280px 1fr; gap: 16px; }
.dex-entry-art { display: flex; flex-direction: column; align-items: center; gap: 11px; padding: 16px; border: 1px solid var(--line); border-radius: 12px; background: radial-gradient(circle at 50% 30%, rgba(255,226,122,0.08), transparent 62%), rgba(0,0,0,0.12); }
.dex-entry-art .pixel-sprite { max-width: 220px; max-height: 220px; filter: drop-shadow(0 14px 16px rgba(0,0,0,0.4)); }
.dex-desc { font-size: 12px; color: var(--ink-soft); text-align: center; line-height: 1.55; }
.dex-meta { width: 100%; display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.dex-entry-main { display: flex; flex-direction: column; gap: 10px; }
.dex-skills { display: flex; flex-direction: column; gap: 3px; }
.dex-skill-row { display: flex; align-items: center; gap: 7px; padding: 3px 4px; border-radius: 6px; font-size: 11px; }
.dex-skill-row .move-icon { width: 22px; height: 22px; flex-basis: 22px; font-size: 10px; }
.dex-skill-row .muted { margin-left: auto; font-family: var(--mono); font-size: 8.5px; }
.evo-line-node { display: flex; align-items: center; gap: 7px; padding: 5px 0; }
.evo-line-node.child { padding-left: 12px; border-left: 1px solid var(--line); margin-left: 8px; flex-wrap: wrap; }
.evo-line-node strong { font-size: 11.5px; }
.evo-arrow { color: var(--gold); font-family: var(--mono); font-size: 12px; }

/* ==========================================================================
   Bag / crafting
   ========================================================================== */
.bag-group { margin-bottom: 15px; }
.item-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 7px; }
.item-card { display: grid; grid-template-columns: 38px minmax(0,1fr) auto; gap: 9px; align-items: center; padding: 8px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.02); }
.item-copy { min-width: 0; }
.item-name-row { display: flex; align-items: baseline; justify-content: space-between; gap: 7px; }
.item-name-row strong { font-size: 12px; }
.item-copy p { font-size: 10.5px; color: var(--muted); line-height: 1.3; }
.craft-intro { font-size: 12.5px; margin-bottom: 13px; }
.recipe-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 8px; }
.recipe-card { display: flex; flex-direction: column; gap: 8px; padding: 11px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,0.018); }
.recipe-card.craftable { border-color: rgba(126,217,87,0.22); background: rgba(126,217,87,0.03); }
.recipe-head { display: flex; gap: 9px; align-items: center; }
.recipe-head > div { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.recipe-head strong { font-size: 12.5px; }
.recipe-cost { display: flex; flex-wrap: wrap; gap: 4px; }
.cost-chip { font-family: var(--mono); font-size: 8.5px; padding: 2px 6px; border-radius: 5px; border: 1px solid var(--line); color: var(--muted); }
.cost-chip.ok { color: #9fe8b0; border-color: rgba(126,217,87,0.25); background: rgba(126,217,87,0.06); }
.cost-chip.missing { color: #ffab9b; border-color: rgba(255,122,122,0.22); background: rgba(255,122,122,0.05); }
.recipe-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; }

/* ==========================================================================
   Map
   ========================================================================== */
.map-screen { display: grid; grid-template-columns: minmax(0,1fr) 280px; gap: 14px; }
.map-canvas-wrap { min-width: 0; border: 1px solid var(--line); border-radius: 12px; overflow: auto; background: #070c0d; }
.map-canvas { display: block; width: 100%; height: auto; image-rendering: pixelated; }
.map-side { display: flex; flex-direction: column; gap: 8px; }
.map-side .panel-soft h3 { font-size: 15px; }
.map-coords { font-family: var(--mono); font-size: 9px; letter-spacing: 0.08em; color: var(--gold); margin-top: 7px; }
.boss-checklist { display: flex; flex-direction: column; gap: 4px; }
.boss-check { display: grid; grid-template-columns: 15px minmax(0,1fr) auto; gap: 5px; font-size: 10.5px; align-items: center; }
.boss-check .done { color: var(--green); }
.boss-check .muted { font-family: var(--mono); font-size: 8.5px; }
.map-help { font-size: 11px; color: var(--muted); line-height: 1.5; }
.map-legend { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 12px; padding: 7px 10px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255,255,255,0.02); font-family: var(--mono); font-size: 8.5px; color: var(--muted); }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.legend-dot { display: inline-block; width: 8px; height: 8px; border-radius: 99px; }
.legend-dot.player { background: #7ed957; box-shadow: 0 0 6px #7ed957; }
.legend-dot.town { background: #ffe27a; }
.legend-dot.boss { background: #ff9a6a; }
.legend-dot.mythic { background: #b48ae0; }

/* ==========================================================================
   Quests / achievements
   ========================================================================== */
.quest-list { display: flex; flex-direction: column; gap: 8px; }
.quest-card { padding: 13px 15px; border: 1px solid var(--line); border-left: 3px solid rgba(255,255,255,0.12); border-radius: 10px; background: rgba(255,255,255,0.022); }
.quest-card.ready { border-left-color: var(--gold); background: linear-gradient(90deg, rgba(255,226,122,0.07), rgba(255,255,255,0.015)); }
.quest-card.tracked { border-color: rgba(255,226,122,0.24); }
.quest-card.compact { padding: 10px 12px; }
.quest-card.done { opacity: 0.72; border-left-color: var(--green); }
.quest-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.quest-card-head h3 { font-size: 14px; }
.quest-card-head .eyebrow { margin-bottom: 2px; }
.quest-desc { font-size: 12px; color: var(--ink-soft); margin: 6px 0 8px; }
.objective-list { display: flex; flex-direction: column; gap: 5px; margin: 8px 0; }
.objective { display: flex; flex-direction: column; gap: 3px; }
.objective-label { display: flex; justify-content: space-between; gap: 8px; font-size: 10.5px; color: var(--muted); }
.objective.done .objective-label { color: #9fe8b0; }
.objective-count { font-family: var(--mono); font-size: 8.5px; }
.reward-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.reward-money, .reward-xp, .reward-chip { font-family: var(--mono); font-size: 8.5px; color: var(--muted); padding: 2px 6px; border-radius: 5px; border: 1px solid var(--line); }
.reward-money { color: var(--gold); border-color: rgba(255,226,122,0.2); }
.achievement-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 10px; }
.achievement-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px,1fr)); gap: 7px; }
.achievement-card { position: relative; display: flex; align-items: center; gap: 9px; padding: 9px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.018); opacity: 0.62; }
.achievement-card.unlocked { opacity: 1; border-color: rgba(255,226,122,0.24); background: linear-gradient(90deg, rgba(255,226,122,0.06), rgba(255,255,255,0.015)); }
.achievement-icon { width: 32px; height: 32px; flex: 0 0 32px; display: grid; place-items: center; border-radius: 8px; background: rgba(255,255,255,0.05); border: 1px solid var(--line); color: var(--muted); font-size: 15px; }
.achievement-card.unlocked .achievement-icon { color: var(--gold); border-color: rgba(255,226,122,0.25); background: rgba(255,226,122,0.08); }
.achievement-card strong { font-size: 11.5px; display: block; }
.achievement-card p { font-size: 10px; color: var(--muted); line-height: 1.35; }
.ach-check { margin-left: auto; color: var(--green); font-size: 12px; }

/* ==========================================================================
   Menu / settings / help
   ========================================================================== */
.menu-screen { display: flex; flex-direction: column; gap: 13px; }
.menu-trainer { display: grid; grid-template-columns: 64px 1fr; gap: 12px; align-items: center; padding: 13px; border: 1px solid var(--line); border-radius: 11px; background: linear-gradient(160deg, rgba(255,226,122,0.06), rgba(0,0,0,0.12)); }
.menu-avatar { width: 56px; height: 56px; }
.menu-trainer h3 { font-size: 15px; margin-bottom: 2px; }
.menu-trainer .thin-track { margin-top: 6px; }
.menu-stats { display: flex; flex-wrap: wrap; gap: 4px 12px; margin-top: 6px; font-family: var(--mono); font-size: 8.5px; color: var(--muted); }
.menu-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.menu-actions .btn { justify-content: flex-start; }
.save-meta { text-align: center; margin-top: 2px; }

.settings-screen { display: flex; flex-direction: column; gap: 2px; }
.toggle-row, .setting-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 10px 4px; border-bottom: 1px solid rgba(255,255,255,0.05); }
.toggle-row:last-child, .setting-row:last-child { border-bottom: 0; }
.toggle-row > div, .setting-row > div { display: flex; flex-direction: column; gap: 1px; }
.toggle-row strong, .setting-row strong { font-size: 12.5px; }
.toggle-row span, .setting-row span { font-size: 10.5px; color: var(--muted); }
.toggle { position: relative; display: inline-flex; flex: 0 0 auto; width: 42px; height: 24px; }
.toggle input { position: absolute; opacity: 0; width: 100%; height: 100%; margin: 0; cursor: pointer; z-index: 2; }
.toggle-track { position: absolute; inset: 0; border-radius: 99px; background: rgba(255,255,255,0.1); border: 1px solid var(--line-strong); transition: 0.15s; }
.toggle-track::after { content: ""; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 99px; background: #c8c4b2; transition: 0.15s; }
.toggle input:checked + .toggle-track { background: rgba(126,217,87,0.28); border-color: rgba(126,217,87,0.5); }
.toggle input:checked + .toggle-track::after { transform: translateX(18px); background: #b9f0a1; }
.settings-note { font-size: 11.5px; color: var(--muted); margin-top: 12px; display: flex; flex-direction: column; gap: 4px; }

.help-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; }
.help-card { padding: 14px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,0.022); }
.help-icon { width: 32px; height: 32px; display: grid; place-items: center; border-radius: 8px; background: rgba(255,226,122,0.08); border: 1px solid rgba(255,226,122,0.2); color: var(--gold); font-size: 15px; margin-bottom: 8px; }
.help-card h3 { font-size: 13px; margin-bottom: 3px; }
.help-card p { font-size: 11.5px; color: var(--muted); line-height: 1.5; }

/* ==========================================================================
   Shop
   ========================================================================== */
.shop-head { display: flex; align-items: center; gap: 12px; justify-content: space-between; }
.shop-head .tab-bar { margin-bottom: 0; flex: 1; }
.money-pill { flex: 0 0 auto; font-family: var(--mono); font-size: 11px; color: var(--gold); padding: 6px 10px; border: 1px solid rgba(255,226,122,0.24); border-radius: 99px; background: rgba(255,226,122,0.06); }
.shop-list { display: flex; flex-direction: column; gap: 5px; margin-top: 12px; }
.shop-row { display: grid; grid-template-columns: 38px minmax(0,1fr) auto auto; gap: 9px; align-items: center; padding: 7px 9px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,0.018); }
.shop-copy { min-width: 0; }
.shop-copy strong { font-size: 12px; }
.shop-copy p { font-size: 10.5px; color: var(--muted); line-height: 1.3; }
.shop-price { font-family: var(--mono); font-size: 11px; color: var(--gold); }

/* ==========================================================================
   Breeding / nursery
   ========================================================================== */
.breeding-screen { display: flex; flex-direction: column; gap: 12px; }
.nursery-note { padding: 10px 13px; border: 1px solid var(--line); border-left: 3px solid var(--purple); border-radius: 8px; background: rgba(180,138,224,0.05); display: flex; flex-direction: column; gap: 3px; }
.nursery-note p { font-size: 12px; color: var(--ink-soft); }
.breed-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.breed-slot { display: flex; flex-direction: column; gap: 7px; padding: 11px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,0.018); min-width: 0; }
.breed-empty { min-height: 94px; display: grid; place-items: center; border: 1px dashed var(--line-strong); border-radius: 8px; font-size: 11px; color: var(--muted); }
.breed-chosen { position: relative; display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 7px; border: 1px solid rgba(255,226,122,0.24); border-radius: 8px; background: rgba(255,226,122,0.05); color: var(--ink); }
.breed-chosen .pixel-sprite { width: 72px; height: 72px; }
.breed-chosen strong { font-size: 12px; }
.breed-chosen .change-hint { position: absolute; top: 5px; right: 6px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.06em; color: var(--gold); text-transform: uppercase; }
.breed-list { display: flex; flex-direction: column; gap: 3px; max-height: 155px; overflow: auto; }
.breed-pick { display: flex; align-items: center; gap: 7px; padding: 3px 5px; border: 1px solid transparent; border-radius: 6px; background: rgba(255,255,255,0.02); color: var(--ink); text-align: left; font-size: 10.5px; }
.breed-pick:hover { border-color: rgba(255,226,122,0.22); background: rgba(255,226,122,0.05); }
.breed-pick .pixel-sprite { width: 30px; height: 30px; }
.breed-pick .small-note { margin-left: auto; }
.breed-preview .panel-soft { padding: 12px; }
.egg-preview-row { display: flex; gap: 12px; align-items: center; }
.egg-preview-row p { font-size: 11.5px; color: var(--ink-soft); }
.egg-preview-row .small-note { font-size: 10px; }

/* ==========================================================================
   Dialogue / NPC
   ========================================================================== */
.dialogue-body { display: grid; grid-template-columns: 74px 1fr; gap: 14px; align-items: start; }
.dialogue-portrait { width: 74px; height: 106px; object-fit: contain; padding: 6px; border: 1px solid var(--line); border-radius: 10px; background: radial-gradient(circle at 50% 30%, rgba(255,226,122,0.1), rgba(0,0,0,0.16)); }
.dialogue-copy { display: flex; flex-direction: column; gap: 8px; }
.dialogue-copy p:first-child { font-size: 14px; color: var(--ink); font-style: italic; line-height: 1.6; }
.dialogue-copy p { font-size: 12px; color: var(--muted); }
.npc-quote { font-size: 13px; font-style: italic; color: var(--ink-soft); line-height: 1.6; margin-bottom: 10px; padding-left: 10px; border-left: 2px solid rgba(255,226,122,0.25); }
.trainer-team-preview { display: flex; flex-wrap: wrap; gap: 5px; margin: 6px 0; }
