@keyframes battle-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes hit-flash { 0% { filter: brightness(2.2) saturate(0.4); transform: translateX(0); } 25% { transform: translateX(7px); } 50% { transform: translateX(-5px); } 75% { transform: translateX(3px); } 100% { transform: translateX(0); filter: none; } }
