@keyframes enter-pop { 0% { transform: scale(0.55); opacity: 0; } 70% { transform: scale(1.08); opacity: 1; } 100% { transform: scale(1); } }
@keyframes fx-rise { 0% { opacity: 0; transform: translate(-50%, -20%) scale(0.7); } 18% { opacity: 1; transform: translate(-50%, -50%) scale(1.1); } 100% { opacity: 0; transform: translate(-50%, -150%) scale(1); } }
