@keyframes orb-throw { 0% { transform: translate(20%, 40%) scale(0.7); opacity: 0; } 60% { transform: translate(-50%, -50%) scale(1); opacity: 1; } 100% { transform: translate(-50%, -50%) scale(1); opacity: 1; } }
@keyframes orb-shake { 0%,100% { transform: translate(-50%, -50%) rotate(0); } 20% { transform: translate(-50%, -50%) rotate(-20deg); } 40% { transform: translate(-50%, -50%) rotate(20deg); } 60% { transform: translate(-50%, -50%) rotate(-14deg); } 80% { transform: translate(-50%, -50%) rotate(14deg); } }
@keyframes orb-break { 0% { transform: translate(-50%, -50%) scale(1); opacity: 1; } 100% { transform: translate(-50%, -50%) scale(1.8); opacity: 0; } }

