// Headless battle fuzz: exercises the engine across many random fights.
import { defaultState, newGame, addItem } from '/home/runner/work/Playground2/Playground2/src/game/state.js'
import { createMonster } from '/home/runner/work/Playground2/Playground2/src/game/monsters.js'
import { Battle, trainerEnemies } from '/home/runner/work/Playground2/Playground2/src/game/battle.js'
import { MONSTER_LIST, STARTERS } from '/home/runner/work/Playground2/Playground2/src/data/monsters.js'
import { BIOME_LIST } from '/home/runner/work/Playground2/Playground2/src/data/biomes.js'
import { ORB_TIERS } from '/home/runner/work/Playground2/Playground2/src/data/items.js'

let battles = 0, turns = 0, errors = 0, outcomes = { win: 0, lose: 0, caught: 0, escaped: 0 }
const originalRandom = Math.random

for (let i = 0; i < 300; i++) {
  const state = newGame(STARTERS[i % 3], 'Fuzz')
  state.party = []
  for (let k = 0; k < 3; k++) state.party.push(createMonster(MONSTER_LIST[Math.floor(Math.random() * MONSTER_LIST.length)].id, 5 + Math.floor(Math.random() * 40)))
  for (const orb of ORB_TIERS) addItem(state, orb, 5)
  state.inventory.minor_mend = 5
  const biome = BIOME_LIST[i % BIOME_LIST.length].id
  const enemies = [createMonster(MONSTER_LIST[Math.floor(Math.random() * MONSTER_LIST.length)].id, 5 + Math.floor(Math.random() * 45))]
  if (i % 4 === 0) enemies.push(createMonster(MONSTER_LIST[Math.floor(Math.random() * MONSTER_LIST.length)].id, 5 + Math.floor(Math.random() * 40)))
  const trainer = i % 5 === 0 ? { name: 'Fuzz Trainer', team: [], reward: 100 } : null
  const battle = new Battle({ state, enemies, trainer, source: { kind: trainer ? 'trainer' : (i % 7 === 0 ? 'boss' : 'wild') }, biome })
  try {
    battle.start()
    let guard = 0
    while (!battle.over && guard++ < 200) {
      turns++
      let action
      if (battle.awaitingSwitch) { action = { type: 'switch', index: battle.playerParty.findIndex(m => m.hp > 0) } }
      else {
        const roll = Math.random()
        if (roll < 0.12 && battle.canCapture) {
          const opts = battle.captureOptions()
          if (opts.length) action = { type: 'capture', itemId: opts[0].id }
        }
        if (!action && roll < 0.2) {
          action = { type: 'item', itemId: 'minor_mend', targetIndex: battle.activeIndex }
        }
        if (!action && roll < 0.26) action = { type: 'switch', index: Math.floor(Math.random() * battle.playerParty.length) }
        if (!action && roll < 0.3 && battle.canEscape) action = { type: 'escape' }
        if (!action) action = { type: 'move', index: Math.floor(Math.random() * battle.active.moves.length) }
      }
      const res = battle.takeTurn(action)
      // consume every event so getters/format logic would run
      for (const ev of res.events || []) { if (ev.type === 'captured') battle.caughtMonster = ev.monster }
    }
    if (battle.over) outcomes[battle.result] = (outcomes[battle.result] || 0) + 1
    else { console.log('NO END', i, battle.turn, battle.active?.hp, battle.enemy?.hp); errors++ }
    battles++
  } catch (err) {
    errors++
    console.log('ERR', i, err.stack.split('\n').slice(0, 3).join(' | '))
    if (errors > 8) break
  }
}
Math.random = originalRandom
console.log({ battles, turns, errors, outcomes })

